   153	};
   154	
   155	#ifdef RT_USING_PM
   156	static int drv_pwm_suspend(const struct rt_device *device, rt_uint8_t mode)
   157	{
   158	    switch (mode)
   159	    {
   160	    case PM_SLEEP_MODE_IDLE:
   161	        break;
   162	    case PM_SLEEP_MODE_LIGHT:
   163	    case PM_SLEEP_MODE_DEEP:
   164	    case PM_SLEEP_MODE_STANDBY:
   165	        hal_clk_disable(CLK_PWM);
   166	        break;
   167	    default:
   168	        break;
   169	    }
   170	
   171	    return 0;
   172	}
   173	
   174	static void drv_pwm_resume(const struct rt_device *device, rt_uint8_t mode)
   175	{
   176	    switch (mode)
   177	    {
   178	    case PM_SLEEP_MODE_IDLE:
   179	        break;
   180	    case PM_SLEEP_MODE_LIGHT:
   181	    case PM_SLEEP_MODE_DEEP:
   182	    case PM_SLEEP_MODE_STANDBY:
   183	        hal_clk_set_freq(CLK_PWM, PWM_CLK_RATE);
   184	        hal_clk_enable(CLK_PWM);
   185	        break;
   186	    default:
   187	        break;
   188	    }
   189	}
   190	
   191	static struct rt_device_pm_ops drv_pwm_pm_ops =
   192	{
   193	    SET_LATE_DEVICE_PM_OPS(drv_pwm_suspend, drv_pwm_resume)
   194	    NULL,
   195	};
   196	#endif
   197	
   198	irqreturn_t aic_pwm_irq(int irq, void *arg)
   199	{
   200	    static u32 isr_cnt[AIC_PWM_CH_NUM] = {0};
   201	    u32 stat;
   202	    int i;
   203	
   204	    stat = hal_pwm_int_sts();
   205	
   206	    for (i = 0; i < AIC_PWM_CH_NUM; i++) {
   207	        if (stat & (1 << i)) {
   208	            isr_cnt[i]++;
   209	            if (isr_cnt[i] == g_pulse_para[i].pulse_cnt) {
   210	                hal_pwm_set(i, g_pulse_para[i].prd_ns, g_pulse_para[i].prd_ns, (rt_uint32_t)PWM_SET_CMPA_CMPB);
   211	                hal_pwm_int_config(i, 0, 0);
   212	                pr_info("\nisr cnt:%d,disabled the pwm%d interrupt now.\n", isr_cnt[i], i);
   213	                isr_cnt[i] = 0;
   214	            }
   215	        }
   216	    }
   217	
   218	    hal_pwm_clr_int(stat);
   219	
   220	    return IRQ_HANDLED;
   221	}
