   230	    if (rt_device_pwm_register(&g_aic_pwm, "pwm", &aic_pwm_ops, NULL))
   231	        return -RT_ERROR;
   232	
   233	#ifdef RT_USING_PM
   234	    rt_pm_device_register(&g_aic_pwm.parent, &drv_pwm_pm_ops);
   235	#endif
   236	
   237	    LOG_I("ArtInChip PWM loaded");
   238	    return RT_EOK;
   239	}
