   121	
   122	  nxmutex_lock(&priv->lock);
   123	
   124	  if (priv->enabled) {
   125	    ret = hal_pwm_disable(priv->pwm_id);
   126	    if (ret < 0) {
   127	      hal_log_err("Failed to disable PWM%d before restart: %d\n", priv->pwm_id, ret);
   128	      nxmutex_unlock(&priv->lock);
   129	      return ret;
   130	    }
   131	    priv->enabled = false;
   132	  }
   133	
   134	  period_ns = PWM_10M_Hz_ns / info->frequency;
   135	
   136	  for (i = 0; i < CONFIG_PWM_NCHANNELS; i++) {
   137	    if (info->channels[i].channel <= 0) {
   138	      continue;
   139	    }
   140	    duty_ns[i] = info->channels[i].duty * period_ns /0xffff;
   141	    if (info->channels[i].cpol != PWM_CPOL_NDEF) {
   142	      enum pwm_polarity polarity = (info->channels[i].cpol == PWM_CPOL_HIGH) ?
   143	                                   PWM_POLARITY_NORMAL : PWM_POLARITY_INVERSED;
   144	      ret = hal_pwm_set_polarity(priv->pwm_id, polarity);
   145	      if (ret < 0) {
   146	        hal_log_err("Failed to set PWM%d polarity: %d\n", priv->pwm_id, ret);
   147	        nxmutex_unlock(&priv->lock);
   148	        return ret;
   149	      }
   150	    }
   151	
   152	    priv->channels[i] = info->channels[i];
   153	  }
   154	
   155	  ret = hal_pwm_set(priv->pwm_id, duty_ns[0], period_ns, PWM_SET_CMPA);
   156	  if (ret < 0) {
   157	    hal_log_err("Failed to set PWM%d: %d\n", priv->pwm_id, ret);
   158	    nxmutex_unlock(&priv->lock);
   159	    return ret;
   160	  }
   161	
   162	  if (CONFIG_PWM_NCHANNELS > 1) {
   163	    ret = hal_pwm_set(priv->pwm_id, duty_ns[1], period_ns, PWM_SET_CMPB);
   164	    if (ret < 0) {
   165	      hal_log_err("Failed to set PWM%d channel B: %d\n", priv->pwm_id, ret);
   166	      nxmutex_unlock(&priv->lock);
   167	      return ret;
   168	    }
   169	  }
   170	
   171	  ret = hal_pwm_enable(priv->pwm_id);
   172	  if (ret < 0) {
   173	    hal_log_err("Failed to enable PWM%d: %d\n", priv->pwm_id, ret);
   174	    nxmutex_unlock(&priv->lock);
   175	    return ret;
   176	  }
   177	
   178	  priv->frequency = info->frequency;
   179	  priv->enabled = true;
   180	
   181	  nxmutex_unlock(&priv->lock);
   182	  return OK;
   183	}
   184	#endif
   185	
   186	static int pwm_start(struct pwm_lowerhalf_s *dev, const struct pwm_info_s *info)
   187	{
   188	  struct aic_pwm_lowerhalf_s *priv = to_aic_pwm(dev);
   189	  int ret = OK;
   190	  uint32_t duty_ns = 0, period_ns = 0;
   191	  float freq;
   192	  uint32_t duty;
   193	  uint32_t frequency;
   194	  uint8_t cpol;
   195	
   196	  if (!info || info->frequency == 0) {
   197	    hal_log_err("PWM info is NULL\n");
   198	    return -EINVAL;
   199	  }
   200	  nxmutex_lock(&priv->lock);
   201	
   202	  
   203	  if (info) {
   204	    duty = info->duty;
   205	    frequency = info->frequency;
   206	    cpol = info->cpol;
   207	  } 
   208	
   209	
   210	#ifdef CONFIG_PWM_MULTICHAN
   211	  nxmutex_unlock(&priv->lock);
   212	  return pwm_start_multichan(priv, info);
   213	#else
   214	  if (priv->enabled) {
   215	    ret = hal_pwm_disable(priv->pwm_id);
   216	    if (ret < 0) {
   217	      hal_log_err("Failed to disable PWM%d before restart: %d\n", priv->pwm_id, ret);
   218	      nxmutex_unlock(&priv->lock);
   219	      return ret;
   220	    }
   221	    priv->enabled = false;
   222	    hal_log_info("PWM%d was enabled, stopped for restart\n", priv->pwm_id);
   223	  }
   224	
   225	  period_ns = NSEC_PER_SEC / frequency;
   226	  freq = (float)duty / 0xffff;
   227	  duty_ns = (uint32_t)(period_ns * freq);
   228	
   229	  if (cpol != PWM_CPOL_NDEF) {
   230	    enum pwm_polarity polarity = (cpol == PWM_CPOL_HIGH)
   231	                                     ? PWM_POLARITY_NORMAL
   232	                                     : PWM_POLARITY_INVERSED;
   233	    hal_log_info("PWM%d set polarity %d\n", priv->pwm_id, polarity);
   234	    ret = hal_pwm_set_polarity(priv->pwm_id, polarity);
   235	    if (ret < 0) {
   236	      hal_log_err("Failed to set PWM%d polarity: %d\n", priv->pwm_id, ret);
   237	      nxmutex_unlock(&priv->lock);
   238	      return ret;
   239	    }
   240	    priv->cpol = cpol;
   241	  }
   242	  syslog(LOG_INFO, "PWM%d set duty %d  duty_ns %lu  period_ns %lu\n",
   243	         priv->pwm_id, duty, duty_ns, period_ns);
   244	
   245	  ret = hal_pwm_set(priv->pwm_id, duty_ns, period_ns, PWM_SET_CMPA);
   246	  if (ret < 0) {
   247	    hal_log_err("Failed to set PWM%d: %d\n", priv->pwm_id, ret);
   248	    nxmutex_unlock(&priv->lock);
   249	    return ret;
   250	  }
   251	
   252	  ret = hal_pwm_enable(priv->pwm_id);
   253	  if (ret < 0) {
   254	    hal_log_err("Failed to enable PWM%d: %d\n", priv->pwm_id, ret);
   255	    nxmutex_unlock(&priv->lock);
   256	    return ret;
   257	  }
   258	  priv->duty = duty;
   259	  priv->frequency = frequency;
   260	  priv->cpol = cpol;
   261	  priv->enabled = true;
   262	
   263	  nxmutex_unlock(&priv->lock);
   264	  return OK;
   265	#endif
   266	}
   267	
   268	static int pwm_stop(struct pwm_lowerhalf_s *dev)
   269	{
   270	  struct aic_pwm_lowerhalf_s *priv = to_aic_pwm(dev);
   271	  int ret;
   272	
   273	  nxmutex_lock(&priv->lock);
   274	
   275	  if (!priv->enabled) {
   276	    hal_log_warn("PWM%d is not running, skip stop\n", priv->pwm_id);
   277	    nxmutex_unlock(&priv->lock);
   278	    return OK;
   279	  }
   280	
   281	  ret = hal_pwm_disable(priv->pwm_id);
   282	  if (ret < 0) {
   283	    hal_log_err("Failed to disable PWM%d: %d\n", priv->pwm_id, ret);
   284	    nxmutex_unlock(&priv->lock);
   285	    return ret;
   286	  }
   287	  hal_log_info("PWM%d stop\n", priv->pwm_id);
   288	  priv->enabled = false;
   289	  nxmutex_unlock(&priv->lock);
   290	  return OK;
   291	}
   292	
   293	static int pwm_ioctl(struct pwm_lowerhalf_s *dev, int cmd, unsigned long arg)
   294	{
   295	  struct aic_pwm_lowerhalf_s *priv = to_aic_pwm(dev);
   296	  struct pwm_info_s *info;
   297	
   298	  hal_log_info("PWM%d ioctl 0x%x\n", priv->pwm_id, cmd);
   299	  switch (cmd) {
   300	    case PWMIOC_GETCHARACTERISTICS:
   301	      nxmutex_lock(&priv->lock);
   302	      info = (struct pwm_info_s *)((uintptr_t)arg);
   303	      if (!info) {
   304	        nxmutex_unlock(&priv->lock);
   305	        return -EINVAL;
   306	      }
   307	
   308	      info->frequency = priv->frequency;
   309	
   310	#ifdef CONFIG_PWM_MULTICHAN
   311	      for (int i = 0; i < CONFIG_PWM_NCHANNELS; i++) {
   312	        info->channels[i] = priv->channels[i];
   313	      }
   314	#else
   315	      info->duty = priv->duty;
   316	      info->cpol = priv->cpol;
   317	      info->dcpol = priv->dcpol;
   318	#endif
   319	      info->arg = NULL;
   320	      nxmutex_unlock(&priv->lock);
   321	      return OK;
   322	
   323	    default:
   324	      hal_log_warn("Unsupported PWM ioctl command: 0x%x\n", cmd);
   325	      return -ENOTTY;
   326	  }
   327	}
