   337	int drv_pwm_nuttx_init(void)
   338	{
   339	  int i, ret, err;
   340	  char devname[16];
   341	
   342	  ret = hal_pwm_init();
   343	  if (ret < 0) {
   344	    hal_log_err("Failed to initialize PWM HAL: %d\n", ret);
   345	    return ret;
   346	  }
   347	  err = PWM_ID_MAX_NUM;
   348	  for (i = 0; i < PWM_ID_MAX_NUM; i++) {
   349	    g_aic_pwm[i].dev.ops = &g_pwmops;
   350	    g_aic_pwm[i].pwm_id = i;
   351	    nxmutex_init(&g_aic_pwm[i].lock);
   352	    g_aic_pwm[i].refs = 0;
   353	    g_aic_pwm[i].frequency = 0;
   354	    g_aic_pwm[i].enabled = false;
   355	#ifndef CONFIG_PWM_MULTICHAN
   356	    g_aic_pwm[i].duty = 0;
   357	    g_aic_pwm[i].cpol = PWM_CPOL_NDEF;
   358	    g_aic_pwm[i].dcpol = PWM_DCPOL_NDEF;
   359	#endif
   360	
   361	    snprintf(devname, sizeof(devname), "/dev/pwm%d", i);
   362	    ret = pwm_register(devname, &g_aic_pwm[i].dev);
   363	    if (ret < 0) {
   364	      hal_log_err("Failed to register PWM%d: %d\n", i, ret);
   365	      nxmutex_destroy(&g_aic_pwm[i].lock);
   366	      g_aic_pwm[i].dev.ops = NULL;
   367	      continue;
   368	    }
   369	    err--;
   370	    hal_log_info("Registered PWM%d at %s\n", i, devname);
   371	  }
   372	  if(err == PWM_ID_MAX_NUM){
   373	    hal_pwm_deinit();
   374	    return -EFAULT;
   375	  }
   376	  return OK;
   377	}

