    83	    return -EINVAL;
    84	  }
    85	
    86	  arg->tb_clk_rate = freq;
    87	
    88	  if (arg->clk_rate == arg->tb_clk_rate)
    89	    div = 0;
    90	  else
    91	    div = arg->clk_rate / arg->tb_clk_rate - 1;
    92	
    93	  pwm_writel_bits(div, PWM_TBCTL_CLKDIV_MASK, PWM_TBCTL_CLKDIV_SHIFT,
    94	                  PWM_TBCTL(ch));
    95	
