   158	static int hal_pwm_calculate_div(u32 ch, float tar_freq) {
   159	  struct aic_pwm_arg *arg = &g_pwm_args[ch];
   160	  int div = -1, i = 0;
   161	  uint32_t min_error = 5e6;
   162	  uint32_t tar_freq_int = (uint32_t)(tar_freq * 100);
   163	
   164	  for (i = 0; i < PWM_TBCTL_CLKDIV_MAX; ++i) {
   165	    u32 count_value = arg->clk_rate * 100 / ((i + 1) * tar_freq_int);
   166	    if (count_value < PWM_TBPRD_MAX) {
   167	      uint32_t current_freq = arg->clk_rate * 100 / ((i + 1) * count_value);
   168	      uint32_t error = abs(current_freq - tar_freq_int);
   169	
   170	      if (error < min_error) {
   171	        min_error = error;
   172	        div = i;
   173	      }
   174	    }
   175	  }
   176	
   177	  hal_log_debug("div:%d\n", div);
   178	
   179	  if (div < 0) {
   180	    hal_log_err("calculate div error,should adjust the PWM_CLK_RATE.\n");
   181	    return -1;
   182	  }
   183	
   184	  pwm_writel_bits(div, PWM_TBCTL_CLKDIV_MASK, PWM_TBCTL_CLKDIV_SHIFT,
   185	                  PWM_TBCTL(ch));
   186	
   187	  arg->tb_clk_rate = arg->clk_rate / (div + 1);
   188	
   189	  return 0;
   190	}
