   229	int hal_pwm_set(u32 ch, u32 duty_ns, u32 period_ns, u32 output) {
   230	  struct aic_pwm_arg *arg = NULL;
   231	  u32 prd = 0;
   232	  u64 duty = 0;
   233	  u64 period = 0;
   234	
   235	  if (hal_pwm_ch_check(ch) < 0)
   236	    return -EINVAL;
   237	
   238	  arg = &g_pwm_args[ch];
   239	
   240	  if (!arg->available) {
   241	    hal_log_err("ch%d is unavailable\n", ch);
   242	    return -EINVAL;
   243	  }
   244	  period = NSEC_PER_SEC / period_ns;
   245	  arg->freq = (float)period;
   246	  if (hal_pwm_calculate_div(ch, arg->freq) < 0)
   247	    return -ERANGE;
   248	
   249	  prd = (float)arg->tb_clk_rate / arg->freq;
   250	
   251	  hal_log_debug("output:Freq %d.%03d Hz, prd value %d, Time-base %d Hz\n",
   252	                (int)arg->freq, (int)((arg->freq - (int)arg->freq) * 1000), prd,
   253	                arg->tb_clk_rate);
   254	
   255	  if (arg->mode == PWM_MODE_UP_DOWN_COUNT)
   256	    prd >>= 1;
   257	  else
   258	    prd--;
   259	
   260	  if (prd > PWM_TBPRD_MAX) {
   261	    hal_log_err("ch%d period %d is too big\n", ch, prd);
   262	    return -ERANGE;
   263	  }
   264	  arg->period = prd;
   265	  pwm_writel(prd, PWM_TBPRD(ch));
   266	
   267	  duty = (u64)duty_ns * (u64)prd;
   268	  do_div(duty, period_ns);
   269	  if (duty == prd)
   270	    duty++;
   271	
   272	  arg->duty = (u32)duty;
   273	  switch (output) {
   274	  case PWM_SET_CMPA:
   275	    pwm_writel((u32)duty, PWM_CMPA(ch));
   276	    hal_log_debug("ch%d Set CMPA %u/%u\n", ch, (u32)duty, prd);
   277	    break;
   278	  case PWM_SET_CMPB:
   279	    pwm_writel((u32)duty, PWM_CMPB(ch));
