int hal_pwm_set_tb(u32 ch, int freq) {
  struct aic_pwm_arg *arg = NULL;
  u32 div = 0;

  if (hal_pwm_ch_check(ch) < 0)
    return -EINVAL;

  arg = &g_pwm_args[ch];

  if (!arg->available) {
    hal_log_err("ch%d is unavailable\n", ch);
    return -EINVAL;
  }

  if ((freq > arg->clk_rate) ||
