  ret = hal_pwm_set(priv->pwm_id, duty_ns, period_ns, PWM_SET_CMPA);
  if (ret < 0) {
    hal_log_err("Failed to set PWM%d: %d\n", priv->pwm_id, ret);
    nxmutex_unlock(&priv->lock);
