        PWM_ACT_LOW,  PWM_ACT_NONE, PWM_ACT_HIGH};
    struct aic_pwm_action action1 = {
        /*       CBD,          CBU,          CAD, */
        PWM_ACT_NONE, PWM_ACT_LOW, PWM_ACT_NONE,
        /*      CAU,           PRD,         ZRO  */
        PWM_ACT_NONE, PWM_ACT_NONE,  PWM_ACT_HIGH};

#ifdef AIC_USING_PWM0
