    89	               LVDS_CTL_MODE(lvds->mode));
    90	  reg_set_bits(comp->regs + LVDS_CTL, LVDS_CTL_LINK_MASK,
    91	               LVDS_CTL_LINK(lvds->link_mode));
    92	}
