    94	static void lvds_set_option_config(struct aic_lvds_comp *comp,
    95	                                   struct panel_lvds *lvds) {
    96	  reg_set_bits(comp->regs + LVDS_CTL, LVDS_CTL_SYNC_MODE_MASK,
    97	               LVDS_CTL_SYNC_MODE_EN(AIC_LVDS_SYNC_MODE_EN));
    98	  reg_set_bits(comp->regs + LVDS_CTL, LVDS_CTL_SWAP_MASK,
    99	               LVDS_CTL_SWAP_EN(lvds->link_swap));
   100	
   101	  lvds_0_lanes(comp, lvds->lanes[0]);
   102	  lvds_1_lanes(comp, lvds->lanes[1]);
   103	
   104	  lvds_0_pol(comp, lvds->pols[0]);
   105	  lvds_1_pol(comp, lvds->pols[1]);
   106	
   107	  lvds_phy_0_init(comp, AIC_LVDS_LINK0_PHY);
   108	  lvds_phy_1_init(comp, AIC_LVDS_LINK1_PHY);
   109	}
