   111	static int aic_lvds_enable(void) {
   112	  struct aic_lvds_comp *comp = aic_lvds_request_drvdata();
   113	  if (!comp)
   114	    return -EINVAL;
   115	  struct panel_lvds *lvds = &comp->lvds;
   116	
   117	  lvds_set_mode(comp, lvds);
   118	  lvds_set_option_config(comp, lvds);
   119	
   120	  reg_set_bit(comp->regs + LVDS_CTL, LVDS_CTL_EN);
   121	
   122	  aic_lvds_release_drvdata();
