   136	static int aic_lvds_attach_panel(struct aic_panel *panel,
   137	                                 struct panel_desc *desc) {
   138	  struct aic_lvds_comp *comp = aic_lvds_request_drvdata();
   139	  u64 pll_disp_rate = 0;
   140	  int i = 0;
   141	  struct panel_lvds *lvds;
   142	  u32 pixclk;
   143	  if (!comp)
   144	    return -EINVAL;
   145	
   146	  if (desc) {
   147	    pixclk = desc->timings->pixelclock;
   148	    lvds = desc->lvds;
   149	  } else {
   150	    pixclk = panel->timings->pixelclock;
   151	    lvds = panel->lvds;
   152	  }
   153	  if (!lvds)
   154	    return -EINVAL;
   155	
   156	  if (lvds->lanes[0] == 0)
   157	    lvds->lanes[0] = (u32)AIC_LVDS_LINK0_LANES;
   158	  if (lvds->lanes[1] == 0)
   159	    lvds->lanes[1] = (u32)AIC_LVDS_LINK1_LANES;
   160	
   161	  comp->lvds = *lvds;
   162	  comp->panel = panel;
   163	  comp->pixclk = pixclk;
   164	
   165	  if (lvds->link_mode != DUAL_LINK)
   166	    comp->sclk_rate = (u64)pixclk * 7;
   167	  else
   168	    comp->sclk_rate = (u64)pixclk * 3 + (pixclk >> 1); // * 3.5
   169	
   170	  pll_disp_rate = comp->sclk_rate;
   171	  while (pll_disp_rate < PLL_DISP_FREQ_MIN) {
   172	    pll_disp_rate = comp->sclk_rate * (2 << i);
   173	    i++;
   174	  }
   175	  comp->pll_disp_rate = pll_disp_rate;
   176	
   177	  aic_lvds_release_drvdata();
   178	  return 0;
   179	}
