   181	static int aic_lvds_get_output_bpp(void) {
   182	  struct aic_lvds_comp *comp = aic_lvds_request_drvdata();
   183	  if (!comp)
   184	    return 24;
   185	  struct panel_lvds *lvds = &comp->lvds;
   186	  int bpp;
   187	
   188	  switch (lvds->mode) {
   189	  case NS:
   190	  case JEIDA_24BIT:
   191	    bpp = 24;
   192	    break;
   193	  case JEIDA_18BIT:
   194	    bpp = 18;
   195	    break;
   196	  default:
   197	    bpp = 24;
   198	    break;
   199	  }
   200	
   201	  aic_lvds_release_drvdata();
   202	  return bpp;
   203	}
