   135	#if DISP_SHOW_FPS == 1
   136	    static int start_cal = 0;
   137	    static int frame_cnt = 0;
   138	    static u64 start_us, end_us;
   139	    int interval = 1000 * 1000;
   140	    int time_diff = 0;
   141	
   142	    if (start_cal == 0) {
   143	        start_cal = 1;
   144	        start_us = (long)aic_get_time_us();
   145	    }
   146	
   147	    end_us = (long)aic_get_time_us();
   148	    time_diff = (int)(end_us - start_us);
   149	    if (time_diff >= interval) {
   150	        aic_disp->fps = frame_cnt;
   151	        frame_cnt = 0;
   152	        start_cal = 0;
   153	    } else {
   154	        frame_cnt++;
   155	    }
   156	#else
   157	    (void)aic_disp;
   158	#endif
   159	    return;
   160	}
