   190	    lv_display_rotation_t rotation = lv_display_get_rotation(disp);
   191	
   192	#if LV_USE_DRAW_GE2D
   193	    lv_draw_ge2d_rotate(disp_buf->data, dest_buf, hor_res, ver_res,
   194	                        src_stride, dst_stride, rotation, cf);
   195	#else
   196	    lv_draw_sw_rotate(disp_buf->data, dest_buf, hor_res, ver_res,
   197	                      src_stride, dst_stride, rotation, cf);
   198	#endif
   199	}
