   214	static inline void disp_draw_buf_flush(aic_disp_t *aic_disp, lv_display_t *disp, lv_draw_buf_t *disp_buf)
   215	{
   216	#if LV_USE_OS && defined(AIC_PAN_DISPLAY)
   217	    wait_sync_ready(aic_disp);
   218	    aic_disp->sync_ready = false;
   219	    disp_do_blit(aic_disp, disp, disp_buf);
   220	    mpp_fb_ioctl(aic_disp->fb, AICFB_PAN_DISPLAY , &aic_disp->buf_id);
   221	
   222	    display_power_on(aic_disp);
   223	    aic_disp->flush_act = true;
   224	    lv_thread_sync_signal(&aic_disp->sync);
   225	#else
   226	#ifdef AIC_PAN_DISPLAY
   227	    disp_do_blit(aic_disp, disp, disp_buf);
   228	    mpp_fb_ioctl(aic_disp->fb, AICFB_PAN_DISPLAY , &aic_disp->buf_id);
   229	
   230	    display_power_on(aic_disp);
   231	    mpp_fb_ioctl(aic_disp->fb, AICFB_WAIT_FOR_VSYNC, 0);
   232	#else
   233	    display_power_on(aic_disp);
   234	    mpp_fb_ioctl(aic_disp->fb, AICFB_WAIT_FOR_VSYNC, 0);
   235	    disp_do_blit(aic_disp, disp, disp_buf);
   236	#endif // AIC_PAN_DISPLAY
   237	#endif
   238	}
