   240	static void disp_flush(lv_display_t *disp, const lv_area_t *area, uint8_t *px_map)
   241	{
   242	    aic_disp_t *aic_disp = (aic_disp_t *)lv_display_get_user_data(disp);
   243	
   244	    lv_draw_buf_t *disp_buf = lv_display_get_buf_active(disp);
   245	    (void)px_map;
   246	
   247	    if (lv_disp_flush_is_last(disp)) {
   248	#if LV_DISP_FB_DUMP
   249	        // dump frame buffer
   250	        lv_disp_buf_dump(disp);
   251	#endif
   252	        if (disp_buf->data == aic_disp->buf_aligned) {
   253	#ifdef AIC_PAN_DISPLAY
   254	            aic_disp->buf_id  =  aic_disp->buf_id > 0 ? 0 : 1;
   255	#else
   256	            aic_disp->buf_id = 0;
   257	#endif
   258	            // flush cache
   259	            aicos_dcache_clean_invalid_range((ulong *)disp_buf->data, (ulong)ALIGN_UP(aic_disp->buf_size, CACHE_LINE_SIZE));
   260	            disp_draw_buf_flush(aic_disp, disp, disp_buf);
   261	        } else {
   262	            // flush cache
   263	            aicos_dcache_clean_invalid_range((ulong *)disp_buf->data, (ulong)ALIGN_UP(aic_disp->fb_size, CACHE_LINE_SIZE));
   264	#ifdef AIC_PAN_DISPLAY
   265	            int index;
   266	            if(disp_buf->data == aic_disp->info.framebuffer) {
   267	                index = 0;
   268	            } else {
   269	                index = 1;
   270	            }
   271	
   272	            // send framebuffer to display
   273	            mpp_fb_ioctl(aic_disp->fb, AICFB_PAN_DISPLAY , &index);
   274	            display_power_on(aic_disp);
   275	            // wait vsync
   276	            mpp_fb_ioctl(aic_disp->fb, AICFB_WAIT_FOR_VSYNC, 0);
   277	#endif
   278	        }
   279	
   280	        display_cal_frame_rate(aic_disp);
   281	    }
   282	
   283	    lv_display_flush_ready(disp);
   284	}
