   310	static void aic_display_thread(void *ptr)
   311	{
   312	    aic_disp_t *aic_disp = (aic_disp_t *)ptr;
   313	
   314	    while(1) {
   315	        while (aic_disp->flush_act == false) {
   316	            if(aic_disp->exit_status)
   317	                break;
   318	
   319	            lv_thread_sync_wait(&aic_disp->sync);
   320	        }
   321	
   322	        aic_disp->flush_act = false;
   323	        mpp_fb_ioctl(aic_disp->fb, AICFB_WAIT_FOR_VSYNC, 0);
   324	        aic_disp->sync_ready = true;
   325	        lv_thread_sync_signal(&aic_disp->sync_notify);
   326	
   327	        if (aic_disp->exit_status) {
   328	            LV_LOG_INFO("Ready to exit aic display thread.");
   329	            break;
   330	        }
   331	    }
   332	
   333	    lv_thread_sync_delete(&aic_disp->sync);
   334	    lv_thread_sync_delete(&aic_disp->sync_notify);
   335	    LV_LOG_INFO("Exit aic display thread.");
   336	}
   337	#endif
