   340	static uint8_t *create_draw_buf(aic_disp_t *aic_disp, int w, int h, lv_color_format_t cf)
   341	{
   342	    int bpp = lv_color_format_get_bpp(cf) / 8;
   343	    int buf_size = ALIGN_UP(w, 8) * ALIGN_UP(h, 8) * bpp;
   344	
   345	    aic_disp->buf = (uint8_t *)aicos_malloc_try_cma(buf_size + CACHE_LINE_SIZE - 1);
   346	    if (!aic_disp->buf) {
   347	        return NULL;
   348	    } else {
   349	        unsigned int align_addr = (unsigned int)ALIGN_UP((ulong) aic_disp->buf, CACHE_LINE_SIZE);
   350	        aic_disp->buf_aligned = (uint8_t *)(ulong)align_addr;
   351	        aicos_dcache_clean_invalid_range((ulong *)(ulong)align_addr, ALIGN_UP(buf_size, CACHE_LINE_SIZE));
   352	    }
   353	
   354	    aic_disp->buf_size = ALIGN_UP(buf_size, CACHE_LINE_SIZE);
   355	    return aic_disp->buf_aligned;
   356	}
