   186	static void aic_de_calc_config(const struct display_timing *timing)
   187	{
   188	    struct aic_de_comp *comp = aic_de_request_drvdata();
   189	
   190	    u32 vtotal = timing->vactive + timing->vfront_porch +
   191	                 timing->vback_porch + timing->vsync_len;
   192	    u32 htotal = timing->hactive + timing->hfront_porch +
   193	                 timing->hback_porch + timing->hsync_len;
   194	    u32 pixelclock = timing->pixelclock;
   195	
   196	    u32 fps = pixelclock / htotal / vtotal;
   197	    u32 frame_us = 1000000 / fps;
   198	    u32 line_us = frame_us / vtotal;
   199	    u32 line = 1;
   200	
   201	    while (line_us < LAYER_CONFIG_TIME_US) {
   202	        line_us = line_us << 1;
   203	        line++;
   204	    }
   205	
   206	    comp->accum_line = vtotal - line - 1;
   207	}
