            // flush cache
            aicos_dcache_clean_invalid_range((ulong *)disp_buf->data, (ulong)ALIGN_UP(aic_disp->buf_size, CACHE_LINE_SIZE));
            disp_draw_buf_flush(aic_disp, disp, disp_buf);
        } else {
