{
    lv_draw_buf_handlers_t *handlers = lv_draw_buf_get_handlers();

    handlers->buf_malloc_cb = lv_aic_cma_draw_buf_malloc;
    handlers->buf_free_cb = lv_aic_cma_draw_buf_free;
    handlers->align_pointer_cb = lv_aic_cma_draw_buf_align;
    handlers->width_to_stride_cb = lv_aic_cma_draw_buf_width_to_stride;
}
