static void * lv_aic_cma_draw_buf_malloc(size_t size_bytes, lv_color_format_t color_format)
{
    LV_UNUSED(color_format);
    size_t aligned_size = ALIGN_UP(size_bytes, CACHE_LINE_SIZE);

    return aicos_malloc_try_cma(aligned_size + CACHE_LINE_SIZE - 1);
}

static void lv_aic_cma_draw_buf_free(void * buf)
{
    if (buf) {
        aicos_free(MEM_CMA, buf);
    }
}

static void * lv_aic_cma_draw_buf_align(void * buf, lv_color_format_t color_format)
{
    LV_UNUSED(color_format);

    return buf ? (void *)ALIGN_UP((ulong)buf, CACHE_LINE_SIZE) : NULL;
}

static uint32_t lv_aic_cma_draw_buf_width_to_stride(uint32_t w, lv_color_format_t color_format)
{
    uint32_t width_byte = w * lv_color_format_get_bpp(color_format);

    width_byte = (width_byte + 7) >> 3;
    return ALIGN_UP(width_byte, CACHE_LINE_SIZE);
}

static void lv_aic_install_draw_buf_handlers(void)
{
    lv_draw_buf_handlers_t *handlers = lv_draw_buf_get_handlers();

    handlers->buf_malloc_cb = lv_aic_cma_draw_buf_malloc;
    handlers->buf_free_cb = lv_aic_cma_draw_buf_free;
    handlers->align_pointer_cb = lv_aic_cma_draw_buf_align;
    handlers->width_to_stride_cb = lv_aic_cma_draw_buf_width_to_stride;
}
