static void lvgl_app_fbdev_compat_update_area(
  struct lvgl_app_fbdev_compat_s *fb,
  lv_display_t *disp,
  const lv_area_t *area)
{
#ifdef CONFIG_FB_UPDATE
  lv_area_t dirty;
  lv_area_t clipped;
  const lv_area_t *update_area = area;
  struct fb_area_s fb_area;

  if (lv_display_flush_is_last(disp) &&
      lv_display_get_dirty_area(disp, &dirty))
    {
      update_area = &dirty;
    }

  if (!lvgl_app_fbdev_compat_clip_area(fb, update_area, &clipped))
    {
      return;
    }

  fb_area.x = clipped.x1;
  fb_area.y = clipped.y1;
  fb_area.w = lv_area_get_width(&clipped);
  fb_area.h = lv_area_get_height(&clipped);

  if (ioctl(fb->fd, FBIO_UPDATE, (unsigned long)((uintptr_t)&fb_area)) < 0)
    {
      syslog(LOG_WARNING, "%s: FBIO_UPDATE failed errno=%d\n",
             LVGL_APP_FBDEV_COMPAT_TAG, errno);
    }
#else
  (void)fb;
  (void)disp;
  (void)area;
#endif
}

