      else if (idle_ms > CONFIG_LVGL_APP_APP_MAIN_LOOP_MAX_SLEEP_MS)
        {
          idle_ms = CONFIG_LVGL_APP_APP_MAIN_LOOP_MAX_SLEEP_MS;
        }

      usleep(idle_ms * 1000u);
    }

  return 0;
}

int main(int argc, char *argv[])
{
  return lvgl_app_entry(argc, argv);
}

