  int ret;

  nxmutex_lock(&priv->lock);

  if (!priv->enabled) {
    hal_log_warn("PWM%d is not running, skip stop\n", priv->pwm_id);
    nxmutex_unlock(&priv->lock);
    return OK;
  }

  ret = hal_pwm_disable(priv->pwm_id);
  if (ret < 0) {
    hal_log_err("Failed to disable PWM%d: %d\n", priv->pwm_id, ret);
    nxmutex_unlock(&priv->lock);
