        nxmutex_unlock(&priv->lock);
        return ret;
      }
    }

    priv->channels[i] = info->channels[i];
  }

  ret = hal_pwm_set(priv->pwm_id, duty_ns[0], period_ns, PWM_SET_CMPA);
