   120	
   121	    dsc->mem = mmap(NULL, dsc->pinfo.fblen, PROT_READ | PROT_WRITE,
   122	                    MAP_SHARED | MAP_FILE, dsc->fd, 0);
   123	    if(dsc->mem == MAP_FAILED) {
   124	        LV_LOG_ERROR("ioctl(FBIOGET_PLANEINFO) failed: %d", errno);
   125	        ret = -errno;
   126	        goto errout;
   127	    }
   128	
   129	    uint32_t w = dsc->vinfo.xres;
   130	    uint32_t h = dsc->vinfo.yres;
   131	    uint32_t stride = dsc->pinfo.stride;
   132	    uint32_t data_size = h * stride;
   133	    lv_draw_buf_init(&dsc->buf1, w, h, LV_COLOR_FORMAT_NATIVE, stride, dsc->mem, data_size);
