   147	    lv_display_set_render_mode(disp, LV_DISP_RENDER_MODE_DIRECT);
   148	    lv_display_set_resolution(disp, dsc->vinfo.xres, dsc->vinfo.yres);
   149	    lv_timer_set_cb(disp->refr_timer, display_refr_timer_cb);
