   331	static void pwm_action_set(u32 ch, struct aic_pwm_action *act, char *name) {
   332	  u32 offset;
   333	  u32 action = g_pwm_args[ch].def_level ? PWM_AQCTL_DEF_LEVEL : 0;
   334	
   335	  if (strcmp(name, "action0") == 0)
   336	    offset = PWM_AQCTLA(ch);
   337	  else
   338	    offset = PWM_AQCTLB(ch);
   339	
   340	  action |=
   341	      (act->CBD << PWM_AQCTL_CBD_SHIFT) | (act->CBU << PWM_AQCTL_CBU_SHIFT) |
   342	      (act->CAD << PWM_AQCTL_CAD_SHIFT) | (act->CAU << PWM_AQCTL_CAU_SHIFT) |
   343	      (act->PRD << PWM_AQCTL_PRD_SHIFT) | act->ZRO;
   344	  pwm_writel(action, offset);
   345	}
