      syslog(LOG_WARNING, "%s: input attach failed: %s\n",
             LVGL_APP_TAG, input_path);
      return;
    }

  if (g_lvgl_result.disp != NULL)
    {
      lv_indev_set_display(indev, g_lvgl_result.disp);
    }

  g_lvgl_result.indev = indev;
