  struct aicfb_info *fbi = aicfb_get_drvdata();
  if (!vtable || !fbi)
    return -EINVAL;

  if (power > 0) {
    return aicfb_ioctl(AICFB_POWERON, NULL);
  } else {
    return aicfb_ioctl(AICFB_POWEROFF, NULL);
  }
}

