void aicfb_enable_panel(struct aicfb_info *fbi, u32 on) {
  struct aic_panel *panel = fbi->panel;
  struct panel_desc *desc = fbi->desc;
  struct aic_panel_funcs *funcs;
  struct platform_driver *di = fbi->di;
  struct platform_driver *de = fbi->de;

  funcs = desc ? desc->funcs : panel->funcs;

  pr_info("aicfb_enable_panel: %s\n", on == AICFB_ON ? "ON" : "OFF");

  if (on == AICFB_ON) {
    pr_info("  Panel name: %s\n", panel->name);
    pr_info("  Connector type: %d\n", panel->connector_type);
    if (panel->timings) {
      pr_info("  Timing: %dx%d, pixelclock=%u Hz (%.2f MHz)\n",
              panel->timings->hactive, panel->timings->vactive,
              panel->timings->pixelclock,
              panel->timings->pixelclock / 1000000.0);
    }
    funcs->prepare();
    pr_info("  Calling di->di_funcs->enable()...\n");
    di->di_funcs->enable();
    if (de && de->de_funcs && de->de_funcs->timing_enable) {
      pr_info("  Calling de->de_funcs->timing_enable()...\n");
      de->de_funcs->timing_enable();
    } else {
      pr_warn("  de or de_funcs or timing_enable is NULL, skipping timing "
              "enable\n");
    }
    pr_info("  Calling funcs->enable()...\n");
    funcs->enable(panel);
  } else {
    funcs->disable(panel);
    if (de && de->de_funcs && de->de_funcs->timing_disable) {
      de->de_funcs->timing_disable();
    }
    di->di_funcs->disable();
    funcs->unprepare();
    pr_info("Panel disabled successfully\n");
  }
}

void aicfb_get_panel_info(struct aicfb_info *fbi) {
  struct platform_driver *de = fbi->de;
  struct platform_driver *di = fbi->di;
  struct aic_panel *panel = fbi->panel;
  u32 bpp = 24, dither_en = 1;
  struct panel_desc *desc = NULL;
  unsigned int id;

  if (panel->desc && panel->match_num) {
    id = panel->match_id;
    desc = &panel->desc[id];
    fbi->desc = desc;
  }

  if (di->di_funcs->attach_panel)
    di->di_funcs->attach_panel(panel, desc);

  if (di->di_funcs->get_output_bpp)
    bpp = di->di_funcs->get_output_bpp();

#ifdef CONFIG_AIC_DISABLE_DITHER
  dither_en = 0;
#endif

  if (de->de_funcs->set_mode)
    de->de_funcs->set_mode(panel, desc, bpp, dither_en);
}

static void aicfb_get_hv_active(struct aicfb_info *fbi, u32 *active_w,
                                u32 *active_h) {
#ifdef CONFIG_AIC_SCREEN_CROP
  *active_w = CONFIG_AIC_SCREEN_CROP_WIDTH;
  *active_h = CONFIG_AIC_SCREEN_CROP_HEIGHT;
#else
  struct aic_panel *panel = fbi->panel;
  struct panel_desc *desc = fbi->desc;

  if (desc) {
    *active_w = desc->timings->hactive;
    *active_h = desc->timings->vactive;
  } else {
    *active_w = panel->timings->hactive;
    *active_h = panel->timings->vactive;
  }
#endif
}

static inline int aicfb_format_bpp(enum mpp_pixel_format format) {
  switch (format) {
  case MPP_FMT_ARGB_8888:
  case MPP_FMT_ABGR_8888:
  case MPP_FMT_RGBA_8888:
  case MPP_FMT_BGRA_8888:
  case MPP_FMT_XRGB_8888:
  case MPP_FMT_XBGR_8888:
  case MPP_FMT_RGBX_8888:
  case MPP_FMT_BGRX_8888:
    return 32;
  case MPP_FMT_RGB_888:
  case MPP_FMT_BGR_888:
    return 24;
  case MPP_FMT_ARGB_1555:
  case MPP_FMT_ABGR_1555:
  case MPP_FMT_RGBA_5551:
  case MPP_FMT_BGRA_5551:
  case MPP_FMT_RGB_565:
  case MPP_FMT_BGR_565:
  case MPP_FMT_ARGB_4444:
  case MPP_FMT_ABGR_4444:
  case MPP_FMT_RGBA_4444:
  case MPP_FMT_BGRA_4444:
    return 16;
  default:
    break;
  }
  return 32;
}

void aicfb_fb_info_setup(struct aicfb_info *fbi) {
  u32 stride, bpp;
  u32 active_w;
  u32 active_h;
  size_t fb_size;

  bpp = aicfb_format_bpp(AICFB_FORMAT);

#ifdef CONFIG_AIC_FB_ROTATE_EN
  fbi->fb_rotate = CONFIG_AIC_FB_ROTATE_DEGREE;
#else
  fbi->fb_rotate = 0;
#endif

  aicfb_get_hv_active(fbi, &active_w, &active_h);

  if (fbi->fb_rotate == 90 || fbi->fb_rotate == 270) {
    u32 tmp = active_w;

    active_w = active_h;
    active_h = tmp;
  }

  stride = ALIGN_8B(active_w * bpp / 8);
  fb_size = active_h * stride;

  fbi->width = active_w;
  fbi->height = active_h;

  fbi->bits_per_pixel = bpp;
  fbi->stride = stride;
  fbi->fb_size = fb_size;
}

void aicfb_register_panel_callback(struct aicfb_info *fbi) {
  struct platform_driver *de = fbi->de;
  struct platform_driver *di = fbi->di;
  struct aic_panel *panel = fbi->panel;
  struct panel_desc *desc = fbi->desc;
  struct aic_panel_callbacks cb;

  cb.di_enable = di->di_funcs->enable;
  cb.di_disable = di->di_funcs->disable;
  cb.di_send_cmd = di->di_funcs->send_cmd;
  cb.di_set_videomode = di->di_funcs->set_videomode;
  cb.timing_enable = de->de_funcs->timing_enable;
  cb.timing_disable = de->de_funcs->timing_disable;

  if (desc)
    desc->funcs->register_callback(panel, &cb);
  else
    panel->funcs->register_callback(panel, &cb);
}

void fb_color_block(struct aicfb_info *fbi, size_t fb_size) {
#ifdef CONFIG_AIC_DISP_COLOR_BLOCK
#ifdef CONFIG_AIC_FB_ROTATE_EN
  if (!fb_size)
    return;

  memset(fbi->fb_start, 0x0, fb_size);
  hal_dcache_clean_invalidate((unsigned long)fbi->fb_start, fb_size);
#else
  u32 width, height;
  u32 i, j, index;
  unsigned char color[5][3] = {
      {0x00, 0x00, 0xFF}, {0x00, 0xFF, 0x00}, {0xFF, 0x00, 0x00},
      {0x00, 0x00, 0x00}, {0xFF, 0xFF, 0xFF},
  };
  unsigned char *pos = (unsigned char *)fbi->fb_start;
  (void)fb_size;

  width = fbi->width;
  height = fbi->height;

  switch (fbi->bits_per_pixel) {
#if defined(CONFIG_AICFB_ARGB8888) || defined(CONFIG_AICFB_ABGR8888) ||                      \
    defined(CONFIG_AICFB_XRGB8888)
  case 32: {
    for (i = 0; i < height; i++) {
      for (j = 0; j < width; j++) {
        index = (i / 100 + j / 100) % 5;

        *(pos++) = color[index][0];
        *(pos++) = color[index][1];
        *(pos++) = color[index][2];
        *(pos++) = 0;
      }
    }
    break;
  }
#endif
#if defined(CONFIG_AICFB_RGB888)
  case 24: {
    for (i = 0; i < height; i++) {
      for (j = 0; j < width; j++) {
        index = (i / 100 + j / 100) % 5;

        *(pos++) = color[index][0];
        *(pos++) = color[index][1];
        *(pos++) = color[index][2];
      }
    }
    break;
  }
#endif
#if defined(CONFIG_AICFB_RGB565)
  case 16: {
    for (i = 0; i < height; i++) {
      for (j = 0; j < width; j++) {
        index = (i / 100 + j / 100) % 5;

        *(pos++) = (color[index][0] >> 3) | ((color[index][1] & 0x1c) << 3);
        *(pos++) = ((color[index][1] & 0xe0) >> 5) | (color[index][2] & 0xf8);
      }
    }
    break;
  }
#endif
  default:
    *pos = color[0][0];
    index = AICFB_FORMAT;
    i = width;
    j = height;

    pr_info("format(%d) do not support %dx%d color block.\n", index, i, j);
    return;
  }

  aicos_dcache_clean_range((unsigned long*)fbi->fb_start, fbi->fb_size);
#endif /* AIC_FB_ROTATE_EN */
#endif /* AIC_DISP_COLOR_BLOCK */
#ifdef CONFIG_AIC_DISP_BLACK_SCREEN
  if (!fb_size)
    return;

  memset(fbi->fb_start, 0x0, fb_size);
  aicos_dcache_clean_range((unsigned long)fbi->fb_start, fb_size);
#endif
}

