   141	int aic_mmcsd_initialize(int slotno) {
   142	  int ret;
   143	
   144	  g_sdio[slotno] = sdio_initialize(slotno);
   145	  if (g_sdio[slotno] == NULL) {
   146	    mcerr("ERROR: sdio_initialize(%d) failed\n", slotno);
   147	    return -ENODEV;
   148	  }
   149	  g_slotno[slotno] = slotno;
   150	  g_inserted[slotno] = board_aic_sdcard_detect(slotno);
   151	
   152	  mcinfo("INFO: slotno=%d, g_inserted(%d)\n", slotno, g_inserted[slotno]);
   153	  if (g_inserted[slotno]) {
   154	    sdio_mediachange(g_sdio[slotno], g_inserted[slotno]);
   155	    ret = mmcsd_slotinitialize(slotno, g_sdio[slotno]);
   156	    if (ret == OK) {
   157	      aic_mmcsd_mount(slotno, true);
   158	    }
   159	  }
