   446	static uint32_t aic_sdio_get_best_div(uint32_t sclk, uint32_t target_freq) {
   447	  AIC_SDIO_LOG_ARGS("sclk=%" PRIu32 " target_freq=%" PRIu32, sclk, target_freq);
   448	  uint32_t down;
   449	  uint32_t up;
   450	  uint32_t f_down;
   451	  uint32_t f_up;
   452	
   453	  down = sclk / target_freq;
   454	  up = DIV_ROUND_UP(sclk, target_freq);
   455	
   456	  f_down = down == 0 ? sclk : sclk / down;
   457	  f_up = up == 0 ? sclk : sclk / up;
   458	
   459	  if ((f_down - target_freq) < (target_freq - f_up)) {
   460	    return down;
   461	  }
   462	
   463	  return up;
   464	}
