   467	  AIC_SDIO_LOG_ARGS("cmd=%s", get_cmd_name(cmd));
   468	  uint32_t resp = cmd & MMCSD_RESPONSE_MASK;
   469	
   470	  return resp == MMCSD_R1_RESPONSE || resp == MMCSD_R1B_RESPONSE ||
   471	         resp == MMCSD_R2_RESPONSE || resp == MMCSD_R5_RESPONSE ||
   472	         resp == MMCSD_R6_RESPONSE || resp == MMCSD_R7_RESPONSE;
