   475	static uint32_t aic_sdio_data_timeout(struct aic_sdio_priv_s *priv) {
   476	  AIC_SDIO_LOG_ARGS("priv=%p", priv);
   477	  uint32_t total;
   478	  uint32_t lanes;
   479	  uint32_t timeout;
   480	
   481	  total = priv->blocklen * priv->nblocks;
   482	  lanes = priv->pdata->buswidth == SDMC_CTYPE_8BIT
   483	              ? 8
   484	              : (priv->pdata->buswidth == SDMC_CTYPE_4BIT ? 4 : 1);
   485	  timeout = total * 8;
   486	  timeout /= lanes;
   487	  timeout *= 10;
   488	
   489	  if (priv->clock == 0) {
   490	    return AIC_SDIO_POLL_TIMEOUT_MS;
   491	  }
   492	
   493	  timeout /= MAX(priv->clock / 1000, 1);
   494	  if (priv->ddr_mode) {
   495	    timeout /= 2;
   496	  }
   497	
   498	  return MAX(timeout, 1000u);
   499	}
