   501	static uint32_t aic_sdio_build_cmdflags(uint32_t cmd) {
   502	  AIC_SDIO_LOG_ARGS("cmd=%s", get_cmd_name(cmd));
   503	  uint32_t flags = 0;
   504	  uint32_t cmdidx = (cmd & MMCSD_CMDIDX_MASK) >> MMCSD_CMDIDX_SHIFT;
   505	  uint32_t xfr = cmd & MMCSD_DATAXFR_MASK;
   506	
   507	  if (xfr != MMCSD_NODATAXFR) {
   508	    flags |= SDMC_CMD_DAT_EXP;
   509	    if ((xfr & MMCSD_WRXFR) != 0) {
   510	      flags |= SDMC_CMD_DAT_WR;
   511	    }
   512	  }
   513	
   514	  if ((cmd & MMCSD_RESPONSE_MASK) != MMCSD_NO_RESPONSE) {
   515	    flags |= SDMC_CMD_RESP_EXP;
   516	    if ((cmd & MMCSD_RESPONSE_MASK) == MMCSD_R2_RESPONSE) {
   517	      flags |= SDMC_CMD_RESP_LEN;
   518	    }
   519	  }
   520	
   521	  if (aic_sdio_resp_crc_needed(cmd)) {
   522	    flags |= SDMC_CMD_RESP_CRC;
   523	  }
   524	
   525	  if (cmdidx == MMCSD_CMDIDX0) {
   526	    flags |= SDMC_CMD_INIT;
   527	  }
   528	
   529	  if (cmd & MMCSD_STOPXFR) {
   530	    flags |= SDMC_CMD_STOP;
   531	  } else {
   532	    flags |= SDMC_CMD_PRV_DAT_WAIT;
   533	  }
   534	  AIC_SDIO_LOG_ARGS("flags=0x%08" PRIx32 " cmdidx=0x%08" PRIx32 " \
   535	      cmd_start=0x%08" PRIx32 " use_hold_reg=0x%08" PRIx32,
   536	                    flags, cmdidx, SDMC_CMD_START, SDMC_CMD_USE_HOLD_REG);
   537	  return flags | cmdidx | SDMC_CMD_START | SDMC_CMD_USE_HOLD_REG;
   538	}
