   595	static int aic_sdio_setup_bus(struct aic_sdio_priv_s *priv, uint32_t freq) {
   596	  mcinfo("priv=%p freq=%d", priv, freq);
   597	  uint32_t mux;
   598	  uint32_t div;
   599	  uint32_t actual;
   600	
   601	  if (freq == 0) {
   602	    return OK;
   603	  }
   604	
   605	  if ((freq == priv->clock) && !priv->ddr_mode) {
   606	    return OK;
   607	  }
   608	
   609	  if (priv->sclk_rate == freq) {
   610	    mux = 1;
   611	    div = 0;
   612	  } else {
   613	    div = aic_sdio_get_best_div(priv->sclk_rate, freq);
   614	    if (div <= 4) {
   615	      mux = DIV_ROUND_UP(div, 2);
   616	    } else {
   617	      mux = (div % 8) ? 2 : 4;
   618	    }
   619	
   620	    div /= mux * 2;
   621	    if (div > SDMC_CLKCTRL_DIV_MAX) {
   622	      div = SDMC_CLKCTRL_DIV_MAX;
   623	    }
   624	  }
   625	
   626	  if (priv->ddr_mode) {
   627	    div = 0;
   628	    mux = aic_sdio_get_best_div(priv->sclk_rate * 2, freq);
   629	  }
   630	
   631	  actual = div ? priv->sclk_rate / mux / div / 2 : priv->sclk_rate / mux;
   632	  mcinfo(" SDMC%d, sclk %u KHz, clk expt %u KHz(act %u KHz), div %u-%u\n",
   633	         priv->pdata->id, priv->sclk_rate / 1000, freq / 1000, actual / 1000,
   634	         mux, div * 2);
   635	
   636	  aic_sdmc_set_ext_clk_mux(&priv->host, mux);
   637	  hal_sdmc_set_div(&priv->host, div);
   638	  hal_sdmc_set_cmd(&priv->host,
   639	                   SDMC_CMD_PRV_DAT_WAIT | SDMC_CMD_UPD_CLK | SDMC_CMD_START);
   640	  if (hal_sdmc_wait_cmd_started(&priv->host) != 0) {
   641	    return -ETIMEDOUT;
   642	  }
   643	
   644	  hal_sdmc_clk_enable(&priv->host);
   645	  hal_sdmc_set_cmd(&priv->host,
   646	                   SDMC_CMD_PRV_DAT_WAIT | SDMC_CMD_UPD_CLK | SDMC_CMD_START);
   647	  if (hal_sdmc_wait_cmd_started(&priv->host) != 0) {
   648	    return -ETIMEDOUT;
   649	  }
   650	
   651	  /* ID mode is sensitive to sampling edge on some boards/cards.
   652	   * Use a conservative sampling phase at very low clock and restore
   653	   * board-configured phases for transfer clocks.
   654	   */
   655	
   656	  if (freq <= SDMC_CLOCK_MIN) {
   657	    hal_sdmc_set_phase(&priv->host, priv->pdata->drv_phase, 1);
   658	  } else {
   659	    hal_sdmc_set_phase(&priv->host, priv->pdata->drv_phase,
   660	                       priv->pdata->smp_phase);
   661	  }
   662	
   663	  priv->clock = freq;
   664	  return OK;
   665	}
