   712	static int aic_sdio_wait_cmd(struct aic_sdio_priv_s *priv, uint32_t *mask) {
   713	  AIC_SDIO_LOG_ARGS("priv=%p mask=%p", priv, mask);
   714	  clock_t start = clock_systime_ticks();
   715	  clock_t timeout = MSEC2TICK(AIC_SDIO_CMD_TIMEOUT_MS);
   716	
   717	  for (;;) {
   718	    uint32_t stat = hal_sdmc_int_stat(&priv->host);
   719	
   720	    if ((stat & SDMC_INT_FROM_SDIO) != 0) {
   721	      hal_sdmc_int_clr(&priv->host, SDMC_INT_FROM_SDIO);
   722	      aic_sdio_dispatch_function_irq(priv);
   723	      stat &= ~SDMC_INT_FROM_SDIO;
   724	    }
   725	
   726	    if (stat &
   727	        (SDMC_INT_RTO | SDMC_INT_RESP_ERR | SDMC_INT_RCRC | SDMC_INT_HLE)) {
   728	      *mask = stat;
   729	      return -EIO;
   730	    }
   731	
   732	    if (stat & SDMC_INT_CMD_DONE) {
   733	      *mask = stat;
   734	      return OK;
   735	    }
   736	
   737	    /* Some controllers may not raise CMD_DONE for data commands, but
   738	     * RXDR/TXDR/DAT_DONE indicates command/data path has progressed.
   739	     */
   740	
   741	    if (priv->cmd_has_data &&
   742	        (stat & (SDMC_INT_RXDR | SDMC_INT_TXDR | SDMC_INT_DAT_DONE)) != 0) {
   743	      *mask = stat;
   744	      return OK;
   745	    }
   746	
   747	    if ((clock_systime_ticks() - start) > timeout) {
   748	      *mask = stat;
   749	      return -ETIMEDOUT;
   750	    }
   751	  }
   752	}
