   754	static int aic_sdio_wait_data(struct aic_sdio_priv_s *priv,
   755	                              sdio_eventset_t *event) {
   756	  AIC_SDIO_LOG_ARGS("priv=%p event=%p", priv, event);
   757	  clock_t start = clock_systime_ticks();
   758	  clock_t timeout =
   759	      MSEC2TICK(priv->wait_timeout_ms == 0 ? aic_sdio_data_timeout(priv)
   760	                                           : priv->wait_timeout_ms);
   761	
   762	  for (;;) {
   763	    uint32_t stat = hal_sdmc_int_stat(&priv->host);
   764	    size_t old_remaining = priv->remaining_words;
   765	
   766	    if ((stat & SDMC_INT_FROM_SDIO) != 0) {
   767	      hal_sdmc_int_clr(&priv->host, SDMC_INT_FROM_SDIO);
   768	      aic_sdio_dispatch_function_irq(priv);
   769	      stat &= ~SDMC_INT_FROM_SDIO;
   770	    }
   771	
   772	    if ((stat & SDMC_DATA_TOUT) != 0) {
   773	      AIC_SDIO_LOG_ARGS("data timeout stat=0x%08" PRIx32 " rem_words=%zu", stat,
   774	                        priv->remaining_words);
   775	      *event = SDIOWAIT_TIMEOUT;
   776	      return -ETIMEDOUT;
   777	    }
   778	
   779	    if ((stat & SDMC_DATA_ERR) != 0) {
   780	      AIC_SDIO_LOG_ARGS("data error stat=0x%08" PRIx32 " rem_words=%zu", stat,
   781	                        priv->remaining_words);
   782	      *event = SDIOWAIT_ERROR;
   783	      return -EIO;
   784	    }
   785	
   786	    if (priv->remaining_words > 0) {
   787	      if (!priv->write_xfr && (stat & (SDMC_INT_RXDR | SDMC_INT_DAT_DONE))) {
   788	        priv->remaining_words = hal_sdmc_data_rx(
   789	            &priv->host, (u32 *)priv->buffer, priv->remaining_words);
   790	      } else if (priv->write_xfr && (stat & SDMC_INT_TXDR)) {
   791	        priv->remaining_words = hal_sdmc_data_tx(
   792	            &priv->host, (u32 *)priv->buffer, priv->remaining_words);
   793	      }
   794	
   795	      priv->buffer +=
   796	          (old_remaining - priv->remaining_words) * sizeof(uint32_t);
   797	    }
   798	
   799	    if (stat & SDMC_INT_DAT_DONE) {
   800	      *event = SDIOWAIT_TRANSFERDONE;
   801	      return OK;
   802	    }
   803	
   804	    if ((clock_systime_ticks() - start) > timeout) {
   805	      *event = SDIOWAIT_TIMEOUT;
   806	      return -ETIMEDOUT;
   807	    }
   808	  }
   809	}
