   692	static int aic_sdio_wait_cmd(struct aic_sdio_priv_s *priv, uint32_t *mask) {
   693	  AIC_SDIO_LOG_ARGS("priv=%p mask=%p", priv, mask);
   694	  clock_t start = clock_systime_ticks();
   695	  clock_t timeout = MSEC2TICK(AIC_SDIO_CMD_TIMEOUT_MS);
   696	
   697	  for (;;) {
   698	    uint32_t stat = hal_sdmc_int_stat(&priv->host);
   699	
   700	    if (stat &
   701	        (SDMC_INT_RTO | SDMC_INT_RESP_ERR | SDMC_INT_RCRC | SDMC_INT_HLE)) {
   702	      *mask = stat;
   703	      return -EIO;
   704	    }
   705	
   706	    if (stat & SDMC_INT_CMD_DONE) {
   707	      *mask = stat;
   708	      return OK;
   709	    }
   710	
   711	    /* Some controllers may not raise CMD_DONE for data commands, but
   712	     * RXDR/TXDR/DAT_DONE indicates command/data path has progressed.
   713	     */
   714	
   715	    if (priv->cmd_has_data &&
   716	        (stat & (SDMC_INT_RXDR | SDMC_INT_TXDR | SDMC_INT_DAT_DONE)) != 0) {
   717	      *mask = stat;
   718	      return OK;
   719	    }
   720	
   721	    if ((clock_systime_ticks() - start) > timeout) {
   722	      *mask = stat;
   723	      return -ETIMEDOUT;
   724	    }
   725	  }
   726	}
   727	
   728	static int aic_sdio_wait_data(struct aic_sdio_priv_s *priv,
   729	                              sdio_eventset_t *event) {
   730	  AIC_SDIO_LOG_ARGS("priv=%p event=%p", priv, event);
   731	  clock_t start = clock_systime_ticks();
   732	  clock_t timeout =
   733	      MSEC2TICK(priv->wait_timeout_ms == 0 ? aic_sdio_data_timeout(priv)
   734	                                           : priv->wait_timeout_ms);
   735	
   736	  for (;;) {
   737	    uint32_t stat = hal_sdmc_int_stat(&priv->host);
   738	    size_t old_remaining = priv->remaining_words;
   739	
   740	    if ((stat & SDMC_DATA_TOUT) != 0) {
   741	      AIC_SDIO_LOG_ARGS("data timeout stat=0x%08" PRIx32 " rem_words=%zu", stat,
   742	                        priv->remaining_words);
   743	      *event = SDIOWAIT_TIMEOUT;
   744	      return -ETIMEDOUT;
   745	    }
   746	
   747	    if ((stat & SDMC_DATA_ERR) != 0) {
   748	      AIC_SDIO_LOG_ARGS("data error stat=0x%08" PRIx32 " rem_words=%zu", stat,
   749	                        priv->remaining_words);
   750	      *event = SDIOWAIT_ERROR;
   751	      return -EIO;
   752	    }
   753	
   754	    if (priv->remaining_words > 0) {
   755	      if (!priv->write_xfr && (stat & (SDMC_INT_RXDR | SDMC_INT_DAT_DONE))) {
   756	        priv->remaining_words = hal_sdmc_data_rx(
   757	            &priv->host, (u32 *)priv->buffer, priv->remaining_words);
   758	      } else if (priv->write_xfr && (stat & SDMC_INT_TXDR)) {
   759	        priv->remaining_words = hal_sdmc_data_tx(
   760	            &priv->host, (u32 *)priv->buffer, priv->remaining_words);
   761	      }
   762	
   763	      priv->buffer +=
   764	          (old_remaining - priv->remaining_words) * sizeof(uint32_t);
   765	    }
   766	
   767	    if (stat & SDMC_INT_DAT_DONE) {
   768	      *event = SDIOWAIT_TRANSFERDONE;
   769	      return OK;
   770	    }
   771	
   772	    if ((clock_systime_ticks() - start) > timeout) {
   773	      *event = SDIOWAIT_TIMEOUT;
   774	      return -ETIMEDOUT;
   775	    }
   776	  }
   777	}
