+int aic_sdio_register_sdio_irq(struct sdio_dev_s *dev, uint8_t function,
+                               worker_t callback, void *arg) {
+  struct aic_sdio_priv_s *priv;
+  irqstate_t flags;
+
+  if (dev == NULL || callback == NULL || function >= AIC_SDIO_NFUNCTIONS) {
+    return -EINVAL;
+  }
+
+  priv = aic_priv(dev);
+  flags = enter_critical_section();
+  priv->sdioirq_callback[function] = callback;
+  priv->sdioirq_arg[function] = arg;
+  leave_critical_section(flags);
+
+  return OK;
+}
+
+int aic_sdio_unregister_sdio_irq(struct sdio_dev_s *dev, uint8_t function) {
+  struct aic_sdio_priv_s *priv;
+  irqstate_t flags;
+
+  if (dev == NULL || function >= AIC_SDIO_NFUNCTIONS) {
+    return -EINVAL;
+  }
+
+  priv = aic_priv(dev);
+  flags = enter_critical_section();
+  priv->sdioirq_callback[function] = NULL;
+  priv->sdioirq_arg[function] = NULL;
+  leave_critical_section(flags);
+
+  return OK;
+}
