  if (all) {
    buf[0] = sdmc_readl(host, SDMC_RESP3);
    buf[1] = sdmc_readl(host, SDMC_RESP2);
    buf[2] = sdmc_readl(host, SDMC_RESP1);
    buf[3] = sdmc_readl(host, SDMC_RESP0);
  } else {
    buf[0] = sdmc_readl(host, SDMC_RESP0);
  }
