   779	static int aic_sdio_prepare_transfer(struct aic_sdio_priv_s *priv,
   780	                                     uint8_t *buffer, size_t nbytes,
   781	                                     bool write) {
   782	  AIC_SDIO_LOG_ARGS("priv=%p buffer=%p nbytes=%zu write=%d", priv, buffer,
   783	                    nbytes, write ? 1 : 0);
   784	  if ((nbytes == 0) || ((nbytes & 3) != 0)) {
   785	    return -EINVAL;
   786	  }
   787	
   788	  if (priv->blocklen == 0) {
   789	    priv->blocklen = 512;
   790	  }
   791	
   792	  if (priv->nblocks == 0) {
   793	    priv->nblocks = 1;
   794	  }
   795	
   796	  hal_sdmc_set_blk(&priv->host, priv->blocklen, priv->nblocks);
   797	  hal_sdmc_reset(&priv->host, SDMC_HCTRL1_FIFO_RESET);
   798	  priv->buffer = buffer;
   799	  priv->remaining_words = nbytes / sizeof(uint32_t);
   800	  priv->write_xfr = write;
   801	  priv->data_active = true;
   802	  return OK;
   803	}
   804	
   805	static void aic_sdio_finish_transfer(struct aic_sdio_priv_s *priv) {
   806	  AIC_SDIO_LOG_ARGS("priv=%p", priv);
   807	  priv->buffer = NULL;
   808	  priv->remaining_words = 0;
   809	  priv->write_xfr = false;
   810	  priv->data_active = false;
   811	}
