   813	static void aic_sdio_reset(struct sdio_dev_s *dev) {
   814	  AIC_SDIO_LOG_ARGS("dev=%p", dev);
   815	  struct aic_sdio_priv_s *priv = aic_priv(dev);
   816	  int ret;
   817	
   818	  if (aic_sdio_hwinit(priv) < 0) {
   819	    return;
   820	  }
   821	
   822	  ret = hal_sdmc_reset(&priv->host, SDMC_HCTRL1_RESET_ALL);
   823	  if (ret != 0) {
   824	    mcerr("ERROR: SDMC%d reset failed\n", priv->pdata->id);
   825	    return;
   826	  }
   827	
   828	  priv->clock = 0;
   829	  priv->blocklen = 512;
   830	  priv->nblocks = 1;
   831	  priv->ddr_mode = priv->pdata->data_rate == SDMC_DDR_MODE;
   832	
   833	  ret = aic_sdio_setup_bus(priv, SDMC_CLOCK_MIN);
   834	  if (ret < 0) {
   835	    mcerr("ERROR: SDMC%d setup ID clock failed: %d\n", priv->pdata->id, ret);
   836	    return;
   837	  }
   838	
   839	  hal_sdmc_init(&priv->host);
   840	  hal_sdmc_fifo_init(&priv->host, &priv->host.fifoth_val);
   841	  hal_sdmc_set_phase(&priv->host, priv->pdata->drv_phase,
   842	                     priv->pdata->smp_phase);
   843	  hal_sdmc_set_ddrmode(&priv->host, priv->ddr_mode ? 1 : 0);
   844	  /* Reset to 1-bit; upper layer switches to wide bus after SCR/EXT_CSD. */
   845	  hal_sdmc_set_buswidth(&priv->host, SDMC_CTYPE_1BIT);
   846	  hal_sdmc_clk_enable(&priv->host);
   847	  hal_sdmc_int_clr(&priv->host, SDMC_INT_ALL);
   848	}
