   888	static void aic_sdio_clock(struct sdio_dev_s *dev, enum sdio_clock_e rate) {
   889	  struct aic_sdio_priv_s *priv = aic_priv(dev);
   890	  mcinfo("Line:%d dev=%p rate=%d sclk_rate=%lu", __LINE__, dev, (int)rate, priv->sclk_rate);
   891	  uint32_t freq;
   892	
   893	  switch (rate) {
   894	  case CLOCK_SDIO_DISABLED:
   895	    hal_sdmc_clk_disable(&priv->host);
   896	    priv->clock = 0;
   897	    return;
   898	
   899	  case CLOCK_IDMODE:
   900	    freq = SDMC_CLOCK_MIN;
   901	    break;
   902	
   903	  case CLOCK_MMC_TRANSFER:
   904	    freq = MIN(priv->sclk_rate, (uint32_t)AIC_SDIO_MMC_FREQ);
   905	    break;
   906	
   907	  case CLOCK_SD_TRANSFER_1BIT:
   908	    freq = MIN(priv->sclk_rate, (uint32_t)AIC_SDIO_SD1_FREQ);
   909	    break;
   910	
   911	  case CLOCK_SD_TRANSFER_4BIT:
   912	  default:
   913	    freq = MIN(priv->sclk_rate, (uint32_t)AIC_SDIO_SD4_FREQ);
   914	    break;
   915	  }
   916	
   917	  aic_sdio_setup_bus(priv, freq);
   918	}
