   920	static int aic_sdio_interrupt(int irq, void *context, void *arg) {
   921	  struct aic_sdio_priv_s *priv = (struct aic_sdio_priv_s *)arg;
   922	  uint32_t stat;
   923	
   924	  UNUSED(irq);
   925	  UNUSED(context);
   926	
   927	  if (priv == NULL) {
   928	    return OK;
   929	  }
   930	
   931	  stat = hal_sdmc_int_stat(&priv->host);
   932	  if (stat == 0) {
   933	    return OK;
   934	  }
   935	
   936	  if ((stat & SDMC_INT_FROM_SDIO) != 0) {
   937	    hal_sdmc_int_clr(&priv->host, SDMC_INT_FROM_SDIO);
   938	  }
   939	
   940	  if ((stat & SDMC_INT_DAT_DONE) != 0) {
   941	    hal_sdmc_int_clr(&priv->host, SDMC_INT_DAT_DONE);
   942	  }
   943	
   944	  return OK;
   945	}
