   947	static int aic_sdio_attach(struct sdio_dev_s *dev) {
   948	  struct aic_sdio_priv_s *priv = aic_priv(dev);
   949	  int ret;
   950	
   951	  AIC_SDIO_LOG_ARGS("dev=%p", dev);
