   976	static int aic_sdio_sendcmd(struct sdio_dev_s *dev, uint32_t cmd,
   977	                            uint32_t arg) {
   978	  AIC_SDIO_LOG_ARGS(" START dev=%p cmd=%s(0x%08" PRIx32 ") arg=0x%08" PRIx32,
   979	                    dev, get_cmd_name(cmd), cmd, arg);
   980	  struct aic_sdio_priv_s *priv = aic_priv(dev);
   981	  clock_t start;
   982	
   983	  if (aic_sdio_hwinit(priv) < 0) {
   984	    return -ENODEV;
   985	  }
   986	
   987	  if (((cmd & MMCSD_CMDIDX_MASK) >> MMCSD_CMDIDX_SHIFT) != MMCSD_CMDIDX12) {
   988	    start = clock_systime_ticks();
   989	    while (hal_sdmc_is_busy(&priv->host) != 0) {
   990	      if ((clock_systime_ticks() - start) >
   991	          MSEC2TICK(AIC_SDIO_BUSY_TIMEOUT_MS)) {
   992	        return -EBUSY;
   993	      }
   994	    }
   995	  }
   996	
   997	  hal_sdmc_int_clr(&priv->host, SDMC_INT_ALL);
   998	  priv->cmd_ret = -EINPROGRESS;
   999	  priv->cmd_stat = 0;
  1000	  priv->cmd_has_data = ((cmd & MMCSD_DATAXFR_MASK) != MMCSD_NODATAXFR);
  1001	  hal_sdmc_set_arg(&priv->host, arg);
  1002	  hal_sdmc_set_cmd(&priv->host, aic_sdio_build_cmdflags(cmd));
  1003	  AIC_SDIO_LOG_ARGS(" END dev=%p cmd=%s arg=0x%08" PRIx32, dev,
  1004	                    get_cmd_name(cmd), arg);
  1005	  return OK;
  1006	}
