   451	static bool aic_sdio_resp_crc_needed(uint32_t cmd) {
   452	  AIC_SDIO_LOG_ARGS("cmd=%s", get_cmd_name(cmd));
   453	  uint32_t resp = cmd & MMCSD_RESPONSE_MASK;
   454	
   455	  return resp == MMCSD_R1_RESPONSE || resp == MMCSD_R1B_RESPONSE ||
   456	         resp == MMCSD_R2_RESPONSE || resp == MMCSD_R5_RESPONSE ||
   457	         resp == MMCSD_R6_RESPONSE || resp == MMCSD_R7_RESPONSE;
   458	}
   459	
   460	static uint32_t aic_sdio_data_timeout(struct aic_sdio_priv_s *priv) {
   461	  AIC_SDIO_LOG_ARGS("priv=%p", priv);
   462	  uint32_t total;
   463	  uint32_t lanes;
   464	  uint32_t timeout;
   465	
   466	  total = priv->blocklen * priv->nblocks;
   467	  lanes = priv->pdata->buswidth == SDMC_CTYPE_8BIT
   468	              ? 8
   469	              : (priv->pdata->buswidth == SDMC_CTYPE_4BIT ? 4 : 1);
   470	  timeout = total * 8;
   471	  timeout /= lanes;
   472	  timeout *= 10;
   473	
   474	  if (priv->clock == 0) {
   475	    return AIC_SDIO_POLL_TIMEOUT_MS;
   476	  }
   477	
   478	  timeout /= MAX(priv->clock / 1000, 1);
   479	  if (priv->ddr_mode) {
   480	    timeout /= 2;
   481	  }
   482	
   483	  return MAX(timeout, 1000u);
   484	}
