   486	static uint32_t aic_sdio_build_cmdflags(uint32_t cmd) {
   487	  AIC_SDIO_LOG_ARGS("cmd=%s", get_cmd_name(cmd));
   488	  uint32_t flags = 0;
   489	  uint32_t cmdidx = (cmd & MMCSD_CMDIDX_MASK) >> MMCSD_CMDIDX_SHIFT;
   490	  uint32_t xfr = cmd & MMCSD_DATAXFR_MASK;
   491	
   492	  if (xfr != MMCSD_NODATAXFR) {
   493	    flags |= SDMC_CMD_DAT_EXP;
   494	    if ((xfr & MMCSD_WRXFR) != 0) {
   495	      flags |= SDMC_CMD_DAT_WR;
   496	    }
   497	  }
   498	
   499	  if ((cmd & MMCSD_RESPONSE_MASK) != MMCSD_NO_RESPONSE) {
   500	    flags |= SDMC_CMD_RESP_EXP;
   501	    if ((cmd & MMCSD_RESPONSE_MASK) == MMCSD_R2_RESPONSE) {
   502	      flags |= SDMC_CMD_RESP_LEN;
   503	    }
   504	  }
   505	
   506	  if (aic_sdio_resp_crc_needed(cmd)) {
   507	    flags |= SDMC_CMD_RESP_CRC;
   508	  }
   509	
   510	  if (cmdidx == MMCSD_CMDIDX0) {
   511	    flags |= SDMC_CMD_INIT;
   512	  }
   513	
   514	  if (cmd & MMCSD_STOPXFR) {
   515	    flags |= SDMC_CMD_STOP;
   516	  } else {
   517	    flags |= SDMC_CMD_PRV_DAT_WAIT;
   518	  }
   519	  AIC_SDIO_LOG_ARGS("flags=0x%08" PRIx32 " cmdidx=0x%08" PRIx32 " \
   520	      cmd_start=0x%08" PRIx32 " use_hold_reg=0x%08" PRIx32,
   521	                    flags, cmdidx, SDMC_CMD_START, SDMC_CMD_USE_HOLD_REG);
   522	  return flags | cmdidx | SDMC_CMD_START | SDMC_CMD_USE_HOLD_REG;
   523	}
