   525	static void aic_sdio_media_callback(void *arg) {
   526	  AIC_SDIO_LOG_ARGS("arg=%p", arg);
   527	  struct aic_sdio_priv_s *priv = (struct aic_sdio_priv_s *)arg;
   528	
   529	  if (priv == NULL || priv->callback == NULL) {
   530	    return;
   531	  }
   532	
   533	  if ((priv->cdstatus & SDIO_STATUS_PRESENT) != 0) {
   534	    if ((priv->cbevents & SDIOMEDIA_INSERTED) == 0) {
   535	      return;
   536	    }
   537	  } else if ((priv->cbevents & SDIOMEDIA_EJECTED) == 0) {
   538	    return;
   539	  }
   540	
   541	  priv->cbevents = 0;
   542	
   543	  if (up_interrupt_context()) {
