   575	static int aic_sdio_setup_bus(struct aic_sdio_priv_s *priv, uint32_t freq) {
   576	  mcinfo("priv=%p freq=%d", priv, freq);
   577	  uint32_t mux;
   578	  uint32_t div;
   579	  uint32_t actual;
   580	
   581	  if (freq == 0) {
   582	    return OK;
   583	  }
   584	
   585	  if ((freq == priv->clock) && !priv->ddr_mode) {
   586	    return OK;
   587	  }
   588	
   589	  if (priv->sclk_rate == freq) {
   590	    mux = 1;
   591	    div = 0;
   592	  } else {
   593	    div = aic_sdio_get_best_div(priv->sclk_rate, freq);
   594	    if (div <= 4) {
   595	      mux = DIV_ROUND_UP(div, 2);
   596	    } else {
   597	      mux = (div % 8) ? 2 : 4;
   598	    }
   599	
   600	    div /= mux * 2;
   601	    if (div > SDMC_CLKCTRL_DIV_MAX) {
   602	      div = SDMC_CLKCTRL_DIV_MAX;
   603	    }
   604	  }
   605	
   606	  if (priv->ddr_mode) {
   607	    div = 0;
   608	    mux = aic_sdio_get_best_div(priv->sclk_rate * 2, freq);
   609	  }
   610	
   611	  actual = div ? priv->sclk_rate / mux / div / 2 : priv->sclk_rate / mux;
   612	  mcinfo(" SDMC%d, sclk %u KHz, clk expt %u KHz(act %u KHz), div %u-%u\n",
   613	         priv->pdata->id, priv->sclk_rate / 1000, freq / 1000, actual / 1000,
   614	         mux, div * 2);
   615	
   616	  aic_sdmc_set_ext_clk_mux(&priv->host, mux);
   617	  hal_sdmc_set_div(&priv->host, div);
   618	  hal_sdmc_set_cmd(&priv->host,
   619	                   SDMC_CMD_PRV_DAT_WAIT | SDMC_CMD_UPD_CLK | SDMC_CMD_START);
   620	  if (hal_sdmc_wait_cmd_started(&priv->host) != 0) {
   621	    return -ETIMEDOUT;
   622	  }
   623	
   624	  hal_sdmc_clk_enable(&priv->host);
   625	  hal_sdmc_set_cmd(&priv->host,
   626	                   SDMC_CMD_PRV_DAT_WAIT | SDMC_CMD_UPD_CLK | SDMC_CMD_START);
   627	  if (hal_sdmc_wait_cmd_started(&priv->host) != 0) {
   628	    return -ETIMEDOUT;
   629	  }
   630	
   631	  /* ID mode is sensitive to sampling edge on some boards/cards.
   632	   * Use a conservative sampling phase at very low clock and restore
   633	   * board-configured phases for transfer clocks.
   634	   */
   635	
   636	  if (freq <= SDMC_CLOCK_MIN) {
   637	    hal_sdmc_set_phase(&priv->host, priv->pdata->drv_phase, 1);
   638	  } else {
   639	    hal_sdmc_set_phase(&priv->host, priv->pdata->drv_phase,
   640	                       priv->pdata->smp_phase);
   641	  }
   642	
   643	  priv->clock = freq;
   644	  return OK;
   645	}
