   692	static int aic_sdio_wait_cmd(struct aic_sdio_priv_s *priv, uint32_t *mask) {
   693	  AIC_SDIO_LOG_ARGS("priv=%p mask=%p", priv, mask);
   694	  clock_t start = clock_systime_ticks();
   695	  clock_t timeout = MSEC2TICK(AIC_SDIO_CMD_TIMEOUT_MS);
   696	
   697	  for (;;) {
   698	    uint32_t stat = hal_sdmc_int_stat(&priv->host);
   699	
   700	    if (stat &
   701	        (SDMC_INT_RTO | SDMC_INT_RESP_ERR | SDMC_INT_RCRC | SDMC_INT_HLE)) {
   702	      *mask = stat;
   703	      return -EIO;
   704	    }
   705	
   706	    if (stat & SDMC_INT_CMD_DONE) {
   707	      *mask = stat;
   708	      return OK;
   709	    }
   710	
   711	    /* Some controllers may not raise CMD_DONE for data commands, but
   712	     * RXDR/TXDR/DAT_DONE indicates command/data path has progressed.
   713	     */
   714	
   715	    if (priv->cmd_has_data &&
   716	        (stat & (SDMC_INT_RXDR | SDMC_INT_TXDR | SDMC_INT_DAT_DONE)) != 0) {
   717	      *mask = stat;
   718	      return OK;
   719	    }
   720	
   721	    if ((clock_systime_ticks() - start) > timeout) {
   722	      *mask = stat;
   723	      return -ETIMEDOUT;
   724	    }
   725	  }
   726	}
