   431	static uint32_t aic_sdio_get_best_div(uint32_t sclk, uint32_t target_freq) {
   432	  AIC_SDIO_LOG_ARGS("sclk=%" PRIu32 " target_freq=%" PRIu32, sclk, target_freq);
   433	  uint32_t down;
   434	  uint32_t up;
   435	  uint32_t f_down;
   436	  uint32_t f_up;
   437	
   438	  down = sclk / target_freq;
   439	  up = DIV_ROUND_UP(sclk, target_freq);
   440	
   441	  f_down = down == 0 ? sclk : sclk / down;
   442	  f_up = up == 0 ? sclk : sclk / up;
   443	
   444	  if ((f_down - target_freq) < (target_freq - f_up)) {
   445	    return down;
   446	  }
   447	
   448	  return up;
   449	}
