    97	void hal_sdmc_idma_prepare(struct aic_sdmc_host *host, u32 blksize, u32 blks,
    98	                           struct aic_sdmc_idma_desc *cur_idma,
    99	                           void *bounce_buffer) {
   100	  unsigned long ctrl;
   101	  unsigned int i = 0, flags, cnt, blk_cnt = blks;
   102	  ulong data_start, data_end;
   103	  unsigned int blk_cnt_in_page = PAGE_SIZE / blksize;
   104	
   105	  data_start = (ulong)cur_idma;
   106	  sdmc_writel(host, SDMC_IDMASADDR, (ulong)cur_idma);
   107	
   108	  do {
   109	    flags = SDMC_IDMAC_OWN | SDMC_IDMAC_CH;
   110	    flags |= (i == 0) ? SDMC_IDMAC_FS : 0;
   111	    if (blk_cnt <= blk_cnt_in_page) {
   112	      flags |= SDMC_IDMAC_LD;
   113	      cnt = blksize * blk_cnt;
   114	    } else {
   115	      cnt = blksize * blk_cnt_in_page;
   116	    }
   117	
   118	    hal_sdmc_idma_prepare_desc(cur_idma, flags, cnt,
   119	                               (ulong)bounce_buffer + (i * PAGE_SIZE));
   120	
   121	    cur_idma++;
   122	    if (blk_cnt <= blk_cnt_in_page)
   123	      break;
   124	    blk_cnt -= blk_cnt_in_page;
   125	    i++;
   126	  } while (1);
   127	
   128	  data_end = (ulong)cur_idma;
   129	  aicos_dcache_clean_invalid_range(
   130	      (ulong *)data_start, roundup(data_end - data_start, ARCH_DMA_MINALIGN));
   131	
   132	  ctrl = sdmc_readl(host, SDMC_HCTRL1);
   133	  ctrl |= SDMC_HCTRL1_USE_IDMAC | SDMC_HCTRL1_DMA_RESET;
   134	  sdmc_writel(host, SDMC_HCTRL1, ctrl);
   135	
   136	  ctrl = sdmc_readl(host, SDMC_PBUSCFG);
   137	  ctrl |= SDMC_PBUSCFG_IDMAC_FB | SDMC_PBUSCFG_IDMAC_EN;
   138	  sdmc_writel(host, SDMC_PBUSCFG, ctrl);
   139	}
