   141	int hal_sdmc_fifo_rdy(struct aic_sdmc_host *host, u32 bit, u32 *len) {
   142	  u64 start_us;
   143	
   144	  start_us = aic_get_time_us();
   145	  *len = sdmc_readl(host, SDMC_CTRST);
   146	  while (*len & bit) {
   147	    *len = sdmc_readl(host, SDMC_CTRST);
   148	    if ((aic_get_time_us() - start_us) > SDMC_TIMEOUT) {
   149	      pr_warn("%s() - FIFO underflow timeout\n", __func__);
   150	      return -1;
   151	    }
   152	  }
   153	
   154	  return 0;
   155	}
