   157	int hal_sdmc_data_rx(struct aic_sdmc_host *host, u32 *buf, u32 size) {
   158	  u32 i, len = 0;
   159	
   160	  sdmc_writel(host, SDMC_OINTST, SDMC_INT_RXDR | SDMC_INT_DAT_DONE);
   161	  while (size) {
   162	    if (hal_sdmc_fifo_rdy(host, SDMC_CTRST_FIFO_EMPTY, &len) < 0)
   163	      return size;
   164	
   165	    len = SDMC_CTRST_FCNT(len);
   166	    len = min(size, len);
   167	    for (i = 0; i < len; i++)
   168	      *buf++ = sdmc_readl(host, SDMC_FIFO_DATA);
   169	    size = size > len ? (size - len) : 0;
   170	  }
   171	
   172	  return size;
   173	}
