   176	  u32 i, len = 0;
   177	  u32 fifo_depth =
   178	      (((host->fifoth_val & RX_WMARK_MASK) >> RX_WMARK_SHIFT) + 1) * 2;
   179	
   180	  while (size) {
   181	    if (hal_sdmc_fifo_rdy(host, SDMC_CTRST_FIFO_FULL, &len) < 0)
   182	      return size;
   183	
   184	    len = fifo_depth - SDMC_CTRST_FCNT(len);
   185	    len = min(size, len);
   186	    for (i = 0; i < len; i++)
   187	      sdmc_writel(host, SDMC_FIFO_DATA, *buf++);
   188	    size = size > len ? (size - len) : 0;
   189	  }
   190	
   191	  sdmc_writel(host, SDMC_OINTST, SDMC_INT_TXDR);
   192	  return size;
   193	}
