   216	u32 hal_sdmc_wait_cmd_started(struct aic_sdmc_host *host) {
   217	  int status, timeout = SDMC_TIMEOUT;
   218	
   219	  do {
   220	    status = sdmc_readl(host, SDMC_CMD);
   221	    if (timeout-- < 0) {
   222	      pr_warn("Timeout!\n");
   223	      return -1;
   224	    }
   225	  } while (status & SDMC_CMD_START);
   226	
   227	  return 0;
   228	}
