   241	int hal_sdmc_reset(struct aic_sdmc_host *host, u32 value) {
   242	  u64 start_us;
   243	  u32 ctrl;
   244	
   245	  ctrl = sdmc_readl(host, SDMC_HCTRL1);
   246	  ctrl |= value;
   247	  sdmc_writel(host, SDMC_HCTRL1, ctrl);
   248	
   249	  start_us = aic_get_time_us();
   250	  while (1) {
   251	    ctrl = sdmc_readl(host, SDMC_HCTRL1);
   252	    if (!(ctrl & value))
   253	      return 0;
   254	
   255	    if ((aic_get_time_us() - start_us) > SDMC_TIMEOUT)
   256	      break;
   257	  }
   258	
   259	  return -ETIME;
   260	}
