   266	void aic_sdmc_set_ext_clk_mux(struct aic_sdmc_host *host, u32 mux) {
   267	  u32 temp = sdmc_readl(host, SDMC_DLYCTRL);
   268	
   269	  temp &= ~SDMC_DLYCTRL_EXT_CLK_MUX_MASK;
   270	  switch (mux) {
   271	  case 1:
   272	    temp |= (u32)SDMC_DLYCTRL_EXT_CLK_MUX_1 << SDMC_DLYCTRL_EXT_CLK_MUX_SHIFT;
   273	    break;
   274	  case 2:
   275	    temp |= SDMC_DLYCTRL_EXT_CLK_MUX_2 << SDMC_DLYCTRL_EXT_CLK_MUX_SHIFT;
   276	    break;
   277	  case 4:
   278	  default:
   279	    temp |= SDMC_DLYCTRL_EXT_CLK_MUX_4 << SDMC_DLYCTRL_EXT_CLK_MUX_SHIFT;
   280	    break;
   281	  }
   282	
   283	  sdmc_writel(host, SDMC_DLYCTRL, temp);
   284	}
