   370	void hal_sdmc_fifo_init(struct aic_sdmc_host *host, u32 *thd) {
   371	  if (*thd == 0) {
   372	    u32 depth = 0;
   373	
   374	    depth = sdmc_readl(host, SDMC_FIFOCFG);
   375	    depth = ((depth & RX_WMARK_MASK) >> RX_WMARK_SHIFT) + 1;
   376	    *thd = MSIZE(0x2) | RX_WMARK(depth / 2 - 1) | TX_WMARK(depth / 2);
   377	  }
   378	  sdmc_writel(host, SDMC_FIFOCFG, *thd);
   379	  sdmc_writel(host, SDMC_CTC,
   380	              (512 << SDMC_CTC_CARDTHR_SHIFT) | SDMC_CTC_CARDRDTHR_EN);
   381	}
