   383	void hal_sdmc_soft_reset(struct aic_sdmc_host *host) {
   384	  u32 temp = 0;
   385	
   386	  temp = sdmc_readl(host, SDMC_INTEN);
   387	  sdmc_writel(host, SDMC_INTEN, 0);
   388	
   389	  sdmc_writel(host, SDMC_IDMAINTEN, 0);
   390	
   391	  if (hal_sdmc_reset(host, SDMC_HCTRL1_RESET_ALL)) {
   392	    pr_err("Failed to reset!\n");
   393	    return;
   394	  }
   395	
   396	  sdmc_writel(host, SDMC_INTEN, temp);
   397	
   398	  hal_sdmc_set_cmd(host,
   399	                   SDMC_CMD_PRV_DAT_WAIT | SDMC_CMD_UPD_CLK | SDMC_CMD_START);
   400	
   401	  if (hal_sdmc_wait_cmd_started(host)) {
   402	    pr_err("Failed to wait cmd started!\n");
   403	    return;
   404	  }
   405	
   406	  temp = sdmc_readl(host, SDMC_OINTST);
   407	  sdmc_writel(host, SDMC_OINTST, temp);
   408	}
