   410	void hal_sdmc_init(struct aic_sdmc_host *host) {
   411	  sdmc_writel(host, SDMC_OINTST, 0xFFFFFFFF);
   412	  sdmc_writel(host, SDMC_INTEN, 0);
   413	
   414	  sdmc_writel(host, SDMC_TTMC, 0xFFFFFFFF);
   415	
   416	  sdmc_writel(host, SDMC_IDMAINTEN, 0);
   417	  sdmc_writel(host, SDMC_PBUSCFG, 1);
   418	
   419	#ifdef CONFIG_AIC_SDMC_IRQ_MODE
   420	  sdmc_writel(host, SDMC_HCTRL1,
   421	              sdmc_readl(host, SDMC_HCTRL1) | SDMC_HCTRL1_INT_EN);
   422	  sdmc_writel(host, SDMC_INTEN, SDMC_INT_DAT_DONE);
   423	  host->complete = aicos_sem_create(0);
   424	#endif
   425	}
