   589	  if (priv->sclk_rate == freq) {
   590	    mux = 1;
   591	    div = 0;
   592	  } else {
   593	    div = aic_sdio_get_best_div(priv->sclk_rate, freq);
   594	    if (div <= 4) {
   595	      mux = DIV_ROUND_UP(div, 2);
