   600	    div /= mux * 2;
   601	    if (div > SDMC_CLKCTRL_DIV_MAX) {
   602	      div = SDMC_CLKCTRL_DIV_MAX;
   603	    }
   604	  }
   605	
   606	  if (priv->ddr_mode) {
   607	    div = 0;
   608	    mux = aic_sdio_get_best_div(priv->sclk_rate * 2, freq);
   609	  }
