  1056	static int aic_sdio_sendcmd(struct sdio_dev_s *dev, uint32_t cmd,
  1057	                            uint32_t arg) {
  1058	  AIC_SDIO_LOG_ARGS(" START dev=%p cmd=%s(0x%08" PRIx32 ") arg=0x%08" PRIx32,
  1059	                    dev, get_cmd_name(cmd), cmd, arg);
  1060	  struct aic_sdio_priv_s *priv = aic_priv(dev);
  1061	  clock_t start;
  1062	
  1063	  if (aic_sdio_hwinit(priv) < 0) {
  1064	    return -ENODEV;
  1065	  }
  1066	
  1067	  if (((cmd & MMCSD_CMDIDX_MASK) >> MMCSD_CMDIDX_SHIFT) != MMCSD_CMDIDX12) {
  1068	    start = clock_systime_ticks();
  1069	    while (hal_sdmc_is_busy(&priv->host) != 0) {
  1070	      if ((clock_systime_ticks() - start) >
  1071	          MSEC2TICK(AIC_SDIO_BUSY_TIMEOUT_MS)) {
  1072	        return -EBUSY;
  1073	      }
  1074	    }
  1075	  }
  1076	
  1077	  hal_sdmc_int_clr(&priv->host, AIC_SDIO_HOST_INT_MASK);
  1078	  priv->cmd_ret = -EINPROGRESS;
  1079	  priv->cmd_stat = 0;
  1080	  priv->cmd_has_data = ((cmd & MMCSD_DATAXFR_MASK) != MMCSD_NODATAXFR);
  1081	  hal_sdmc_set_arg(&priv->host, arg);
  1082	  hal_sdmc_set_cmd(&priv->host, aic_sdio_build_cmdflags(cmd));
  1083	  AIC_SDIO_LOG_ARGS(" END dev=%p cmd=%s arg=0x%08" PRIx32, dev,
  1084	                    get_cmd_name(cmd), arg);
  1085	  return OK;
  1086	}
