  1293	static sdio_eventset_t aic_sdio_eventwait(struct sdio_dev_s *dev) {
  1294	  AIC_SDIO_LOG_ARGS("dev=%p", dev);
  1295	  struct aic_sdio_priv_s *priv = aic_priv(dev);
  1296	  sdio_eventset_t event = 0;
  1297	  int ret;
  1298	
  1299	  if (!priv->data_active) {
  1300	    return 0;
  1301	  }
  1302	
  1303	  ret = aic_sdio_wait_data(priv, &event);
  1304	  if (ret < 0 && event == 0) {
  1305	    event = SDIOWAIT_ERROR;
  1306	  }
  1307	
  1308	  if ((event & SDIOWAIT_TRANSFERDONE) != 0) {
  1309	    if (priv->cmd_ret == -EINPROGRESS) {
  1310	      priv->cmd_ret = OK;
  1311	    }
  1312	
  1313	    hal_sdmc_int_clr(&priv->host, SDMC_INT_DAT_DONE);
  1314	  } else {
  1315	    if (priv->cmd_ret == -EINPROGRESS) {
  1316	      if ((event & SDIOWAIT_TIMEOUT) != 0) {
  1317	        priv->cmd_ret = -ETIMEDOUT;
  1318	      } else {
  1319	        priv->cmd_ret = -EIO;
  1320	      }
  1321	    }
  1322	
  1323	    hal_sdmc_int_clr(&priv->host, AIC_SDIO_HOST_INT_MASK);
  1324	  }
  1325	
  1326	  aic_sdio_finish_transfer(priv);
  1327	  priv->wkupevent = event;
  1328	  priv->waitevents = 0;
  1329	  return event;
  1330	}
