   713	static int aic_sdio_wait_cmd(struct aic_sdio_priv_s *priv, uint32_t *mask) {
   714	  AIC_SDIO_LOG_ARGS("priv=%p mask=%p", priv, mask);
   715	  clock_t start = clock_systime_ticks();
   716	  clock_t timeout = MSEC2TICK(AIC_SDIO_CMD_TIMEOUT_MS);
   717	
   718	  for (;;) {
   719	    uint32_t stat = hal_sdmc_int_stat(&priv->host);
   720	
   721	    if ((stat & SDMC_INT_FROM_SDIO) != 0) {
   722	      hal_sdmc_int_clr(&priv->host, SDMC_INT_FROM_SDIO);
   723	      aic_sdio_dispatch_function_irq(priv);
   724	      stat &= ~SDMC_INT_FROM_SDIO;
   725	    }
   726	
   727	    if (stat &
   728	        (SDMC_INT_RTO | SDMC_INT_RESP_ERR | SDMC_INT_RCRC | SDMC_INT_HLE)) {
   729	      *mask = stat;
   730	      return -EIO;
   731	    }
   732	
   733	    if (stat & SDMC_INT_CMD_DONE) {
   734	      *mask = stat;
   735	      return OK;
   736	    }
   737	
   738	    /* Some controllers may not raise CMD_DONE for data commands, but
   739	     * RXDR/TXDR/DAT_DONE indicates command/data path has progressed.
   740	     */
   741	
   742	    if (priv->cmd_has_data &&
   743	        (stat & (SDMC_INT_RXDR | SDMC_INT_TXDR | SDMC_INT_DAT_DONE)) != 0) {
   744	      *mask = stat;
   745	      return OK;
   746	    }
   747	
   748	    if ((clock_systime_ticks() - start) > timeout) {
   749	      *mask = stat;
   750	      return -ETIMEDOUT;
   751	    }
   752	  }
