   755	static int aic_sdio_wait_data(struct aic_sdio_priv_s *priv,
   756	                              sdio_eventset_t *event) {
   757	  AIC_SDIO_LOG_ARGS("priv=%p event=%p", priv, event);
   758	  clock_t start = clock_systime_ticks();
   759	  clock_t timeout =
   760	      MSEC2TICK(priv->wait_timeout_ms == 0 ? aic_sdio_data_timeout(priv)
   761	                                           : priv->wait_timeout_ms);
   762	
   763	  for (;;) {
   764	    uint32_t stat = hal_sdmc_int_stat(&priv->host);
   765	    size_t old_remaining = priv->remaining_words;
   766	
   767	    if ((stat & SDMC_INT_FROM_SDIO) != 0) {
   768	      hal_sdmc_int_clr(&priv->host, SDMC_INT_FROM_SDIO);
   769	      aic_sdio_dispatch_function_irq(priv);
   770	      stat &= ~SDMC_INT_FROM_SDIO;
   771	    }
   772	
   773	    if ((stat & SDMC_DATA_TOUT) != 0) {
   774	      AIC_SDIO_LOG_ARGS("data timeout stat=0x%08" PRIx32 " rem_words=%zu", stat,
   775	                        priv->remaining_words);
   776	      *event = SDIOWAIT_TIMEOUT;
   777	      return -ETIMEDOUT;
   778	    }
   779	
   780	    if ((stat & SDMC_DATA_ERR) != 0) {
   781	      AIC_SDIO_LOG_ARGS("data error stat=0x%08" PRIx32 " rem_words=%zu", stat,
   782	                        priv->remaining_words);
   783	      *event = SDIOWAIT_ERROR;
   784	      return -EIO;
   785	    }
   786	
   787	    if (priv->remaining_words > 0) {
   788	      if (!priv->write_xfr && (stat & (SDMC_INT_RXDR | SDMC_INT_DAT_DONE))) {
   789	        priv->remaining_words = hal_sdmc_data_rx(
   790	            &priv->host, (u32 *)priv->buffer, priv->remaining_words);
   791	      } else if (priv->write_xfr && (stat & SDMC_INT_TXDR)) {
   792	        priv->remaining_words = hal_sdmc_data_tx(
   793	            &priv->host, (u32 *)priv->buffer, priv->remaining_words);
   794	      }
   795	
   796	      priv->buffer +=
   797	          (old_remaining - priv->remaining_words) * sizeof(uint32_t);
   798	    }
   799	
   800	    if (stat & SDMC_INT_DAT_DONE) {
   801	      *event = SDIOWAIT_TRANSFERDONE;
   802	      return OK;
   803	    }
   804	
   805	    if ((clock_systime_ticks() - start) > timeout) {
   806	      *event = SDIOWAIT_TIMEOUT;
   807	      return -ETIMEDOUT;
   808	    }
   809	  }
   810	}
