#ifndef D12X_SDHC_AUTOMOUNT_BLKDEV
#define D12X_SDHC_AUTOMOUNT_BLKDEV "/dev/mmcsd1"
#endif
#define AIC_SDIO_HOTPLUG_POLL_MS 200
#define AIC_SDIO_HOTPLUG_STABLE_SAMPLES 3

/****************************************************************************
