static inline const struct aic_sdio_pdata_s *aic_slot_pdata(int slotno) {
  AIC_SDIO_LOG_ARGS("slotno=%d", slotno);
  if (slotno < 0 || slotno >= AIC_SDIO_NSLOTS) {
