static sdio_eventset_t aic_sdio_eventwait(struct sdio_dev_s *dev) {
  AIC_SDIO_LOG_ARGS("dev=%p", dev);
  struct aic_sdio_priv_s *priv = aic_priv(dev);
  sdio_eventset_t event = 0;
  int ret;

  if (!priv->data_active) {
    return 0;
  }

  ret = aic_sdio_wait_data(priv, &event);
  if (ret < 0) {
    aic_sdio_recover(priv);
  }

  if (ret < 0 && event == 0) {
    event = SDIOWAIT_ERROR;
  }

  if ((event & SDIOWAIT_TRANSFERDONE) != 0) {
    if (priv->cmd_ret == -EINPROGRESS) {
      priv->cmd_ret = OK;
    }

    hal_sdmc_int_clr(&priv->host, SDMC_INT_DAT_DONE);
  } else {
    if (priv->cmd_ret == -EINPROGRESS) {
      if ((event & SDIOWAIT_TIMEOUT) != 0) {
        priv->cmd_ret = -ETIMEDOUT;
      } else {
        priv->cmd_ret = -EIO;
      }
    }

    hal_sdmc_int_clr(&priv->host, AIC_SDIO_HOST_INT_MASK);
  }

  aic_sdio_finish_transfer(priv);
  priv->wkupevent = event;
  priv->waitevents = 0;
  return event;
}

