static int aic_sdio_clk_init(struct aic_sdio_priv_s *priv) {
  AIC_SDIO_LOG_ARGS("priv=%p", priv);
  int ret;

  hal_clk_disable_assertrst(priv->pdata->clk);
  hal_clk_disable(priv->pdata->clk);
  hal_clk_set_freq(priv->pdata->clk, priv->pdata->clk_freq);
  priv->sclk_rate = hal_clk_get_freq(priv->pdata->clk);
  if (priv->pdata->is_sdio) {
    priv->sclk_rate /= 2;
  }

  mcinfo("Line:%d  sclk_rate=%lu buswidth=%d clk_freq=%lu", __LINE__,
         priv->sclk_rate, priv->pdata->buswidth, priv->pdata->clk_freq);
  ret = hal_clk_enable(priv->pdata->clk);
  if (ret < 0) {
    mcerr("ERROR: SDMC%d clk enable failed\n", priv->pdata->id);
    return ret;
  }

  ret = hal_clk_enable_deassertrst(priv->pdata->clk);
  if (ret < 0) {
    mcerr("ERROR: SDMC%d reset deassert failed\n", priv->pdata->id);
    return ret;
  }

  return OK;
}

static int aic_sdio_setup_bus(struct aic_sdio_priv_s *priv, uint32_t freq) {
  mcinfo("priv=%p freq=%d", priv, freq);
  uint32_t mux;
  uint32_t div;
  uint32_t actual;

  if (freq == 0) {
    return OK;
  }

  if ((freq == priv->clock) && !priv->ddr_mode) {
    return OK;
  }

  if (priv->sclk_rate == freq) {
    mux = 1;
    div = 0;
  } else {
    div = aic_sdio_get_best_div(priv->sclk_rate, freq);
    if (div <= 4) {
      mux = DIV_ROUND_UP(div, 2);
    } else {
      mux = (div % 8) ? 2 : 4;
    }

    div /= mux * 2;
    if (div > SDMC_CLKCTRL_DIV_MAX) {
      div = SDMC_CLKCTRL_DIV_MAX;
    }
  }

  if (priv->ddr_mode) {
    div = 0;
    mux = aic_sdio_get_best_div(priv->sclk_rate * 2, freq);
  }

  actual = div ? priv->sclk_rate / mux / div / 2 : priv->sclk_rate / mux;
  mcinfo(" SDMC%d, sclk %u KHz, clk expt %u KHz(act %u KHz), div %u-%u\n",
         priv->pdata->id, priv->sclk_rate / 1000, freq / 1000, actual / 1000,
         mux, div * 2);

  aic_sdmc_set_ext_clk_mux(&priv->host, mux);
  hal_sdmc_set_div(&priv->host, div);
  hal_sdmc_set_cmd(&priv->host,
                   SDMC_CMD_PRV_DAT_WAIT | SDMC_CMD_UPD_CLK | SDMC_CMD_START);
  if (hal_sdmc_wait_cmd_started(&priv->host) != 0) {
    return -ETIMEDOUT;
  }

  hal_sdmc_clk_enable(&priv->host);
  hal_sdmc_set_cmd(&priv->host,
                   SDMC_CMD_PRV_DAT_WAIT | SDMC_CMD_UPD_CLK | SDMC_CMD_START);
  if (hal_sdmc_wait_cmd_started(&priv->host) != 0) {
    return -ETIMEDOUT;
  }

  /* ID mode is sensitive to sampling edge on some boards/cards.
   * Use a conservative sampling phase at very low clock and restore
   * board-configured phases for transfer clocks.
   */

  if (freq <= SDMC_CLOCK_MIN) {
    hal_sdmc_set_phase(&priv->host, priv->pdata->drv_phase, 1);
  } else {
    hal_sdmc_set_phase(&priv->host, priv->pdata->drv_phase,
                       priv->pdata->smp_phase);
  }

  priv->clock = freq;
  return OK;
}

static int aic_sdio_hwinit(struct aic_sdio_priv_s *priv) {
  int ret;

  if (priv->initialized) {
    return OK;
  }
  ret = aic_sdio_clk_init(priv);
  if (ret < 0) {
    return ret;
  }

  priv->host.base = (volatile void *)priv->pdata->base;
  priv->host.is_sdio = priv->pdata->is_sdio ? 1 : 0;
  priv->host.fifoth_val = MSIZE(2) | RX_WMARK(7) | TX_WMARK(8);

  ret = hal_sdmc_reset(&priv->host, SDMC_HCTRL1_RESET_ALL);
  if (ret != 0) {
    return -EIO;
  }

  priv->ddr_mode = priv->pdata->data_rate == SDMC_DDR_MODE;
  priv->blocklen = 512;
  priv->nblocks = 1;
  priv->clock = 0;
  AIC_SDIO_LOG_ARGS("ddr_mode=%d ,", priv->ddr_mode ? 1 : 0);

  ret = aic_sdio_setup_bus(priv, SDMC_CLOCK_MIN);
  if (ret < 0) {
    return ret;
  }

  hal_sdmc_init(&priv->host);
  hal_sdmc_fifo_init(&priv->host, &priv->host.fifoth_val);
  hal_sdmc_set_phase(&priv->host, priv->pdata->drv_phase,
                     priv->pdata->smp_phase);
  hal_sdmc_set_ddrmode(&priv->host, priv->ddr_mode ? 1 : 0);
  /* During identification/init sequence the card is in 1-bit mode. */
  hal_sdmc_set_buswidth(&priv->host, SDMC_CTYPE_1BIT);
  hal_sdmc_clk_enable(&priv->host);

  priv->initialized = true;
  AIC_SDIO_LOG_ARGS("aic_sdio_hwinit END OK");
  return OK;
}

static int aic_sdio_wait_cmd(struct aic_sdio_priv_s *priv, uint32_t *mask) {
  AIC_SDIO_LOG_ARGS("priv=%p mask=%p", priv, mask);
  clock_t start = clock_systime_ticks();
  clock_t timeout = MSEC2TICK(AIC_SDIO_CMD_TIMEOUT_MS);

  for (;;) {
    uint32_t stat = hal_sdmc_int_stat(&priv->host);

    if ((stat & SDMC_INT_FROM_SDIO) != 0) {
      hal_sdmc_int_clr(&priv->host, SDMC_INT_FROM_SDIO);
      aic_sdio_dispatch_function_irq(priv);
      stat &= ~SDMC_INT_FROM_SDIO;
    }
    buf[3] = sdmc_readl(host, SDMC_RESP0);
  } else {
    buf[0] = sdmc_readl(host, SDMC_RESP0);
  }
}

int hal_sdmc_reset(struct aic_sdmc_host *host, u32 value) {
  u64 start_us;
  u32 ctrl;

  ctrl = sdmc_readl(host, SDMC_HCTRL1);
  ctrl |= value;
  sdmc_writel(host, SDMC_HCTRL1, ctrl);

  start_us = aic_get_time_us();
  while (1) {
    ctrl = sdmc_readl(host, SDMC_HCTRL1);
    if (!(ctrl & value))
      return 0;

    if ((aic_get_time_us() - start_us) > SDMC_TIMEOUT)
      break;
  }

  return -ETIME;
}

int hal_sdmc_is_busy(struct aic_sdmc_host *host) {
  return sdmc_readl(host, SDMC_CTRST) & SDMC_CTRST_BUSY;
}

void aic_sdmc_set_ext_clk_mux(struct aic_sdmc_host *host, u32 mux) {
  u32 temp = sdmc_readl(host, SDMC_DLYCTRL);

  temp &= ~SDMC_DLYCTRL_EXT_CLK_MUX_MASK;
  switch (mux) {
  case 1:
    temp |= (u32)SDMC_DLYCTRL_EXT_CLK_MUX_1 << SDMC_DLYCTRL_EXT_CLK_MUX_SHIFT;
    break;
  case 2:
    temp |= SDMC_DLYCTRL_EXT_CLK_MUX_2 << SDMC_DLYCTRL_EXT_CLK_MUX_SHIFT;
    break;
  case 4:
  default:
    temp |= SDMC_DLYCTRL_EXT_CLK_MUX_4 << SDMC_DLYCTRL_EXT_CLK_MUX_SHIFT;
    break;
  }

  sdmc_writel(host, SDMC_DLYCTRL, temp);
}

void hal_sdmc_set_phase(struct aic_sdmc_host *host, u32 drv, u32 smp) {
  u32 temp = 0;

  temp = sdmc_readl(host, SDMC_DLYCTRL);
  temp &= ~SDMC_DLYCTRL_CLK_DRV_PHA_MASK;
  temp &= ~SDMC_DLYCTRL_CLK_SMP_PHA_MASK;
  temp |= drv << SDMC_DLYCTRL_CLK_DRV_PHA_SHIFT |
          smp << SDMC_DLYCTRL_CLK_SMP_PHA_SHIFT;
  sdmc_writel(host, SDMC_DLYCTRL, temp);
}

void hal_sdmc_set_delay(struct aic_sdmc_host *host, u32 drv, u32 smp) {
  u32 temp = 0;

  temp = sdmc_readl(host, SDMC_DLYCTRL);
  temp &= ~SDMC_DLYCTRL_CLK_DRV_DLY_MASK;
  temp &= ~SDMC_DLYCTRL_CLK_SMP_DLY_MASK;
  temp |= drv << SDMC_DLYCTRL_CLK_DRV_DLY_SHIFT |
          smp << SDMC_DLYCTRL_CLK_SMP_DLY_SHIFT;
  sdmc_writel(host, SDMC_DLYCTRL, temp);
}

void hal_sdmc_set_buswidth(struct aic_sdmc_host *host, u32 buswidth) {
  u32 val = 0;

  val = sdmc_readl(host, SDMC_HCTRL2);
  val &= ~(SDMC_CTYPE_RESERVED << SDMC_HCTRL2_BW_SHIFT);
  val |= buswidth << SDMC_HCTRL2_BW_SHIFT;
  sdmc_writel(host, SDMC_HCTRL2, val);
}

void hal_sdmc_set_ddrmode(struct aic_sdmc_host *host, u32 ddr) {
  u32 val = 0;

  val = sdmc_readl(host, SDMC_HCTRL2);
  if (ddr)
    val |= SDMC_HCTRL2_DDR_MODE;
  else
    val &= ~SDMC_HCTRL2_DDR_MODE;
  sdmc_writel(host, SDMC_HCTRL2, val);
}

void hal_sdmc_clk_disable(struct aic_sdmc_host *host) {
  u32 temp = 0;

  temp = sdmc_readl(host, SDMC_CLKCTRL);
  temp &= ~SDMC_CLKCTRL_EN;
  sdmc_writel(host, SDMC_CLKCTRL, temp);
}

void hal_sdmc_clk_enable(struct aic_sdmc_host *host) {
  u32 temp = 0;

  temp = sdmc_readl(host, SDMC_CLKCTRL);
  temp |= SDMC_CLKCTRL_EN;
  if (!host->is_sdio)
    temp |= SDMC_CLKCTRL_LOW_PWR;
  sdmc_writel(host, SDMC_CLKCTRL, temp);
}

void hal_sdmc_sdio_irq_enable(struct aic_sdmc_host *host, u32 en) {
  u32 temp = 0;

  temp = sdmc_readl(host, SDMC_INTEN);
  if (en)
    temp |= SDMC_INT_FROM_SDIO;
  else
    temp &= ~SDMC_INT_FROM_SDIO;
  sdmc_writel(host, SDMC_INTEN, temp);
}

void hal_sdmc_set_div(struct aic_sdmc_host *host, u32 div) {
  u32 temp = 0;

  temp = sdmc_readl(host, SDMC_CLKCTRL);
  temp &= ~SDMC_CLKCTRL_EN;
  sdmc_writel(host, SDMC_CLKCTRL, temp);

  temp = sdmc_readl(host, SDMC_CLKCTRL);
  temp &= ~SDMC_CLKCTRL_DIV_MASK;
  temp |= (div << SDMC_CLKCTRL_DIV_SHIFT) & SDMC_CLKCTRL_DIV_MASK;
  sdmc_writel(host, SDMC_CLKCTRL, temp);
}

void hal_sdmc_fifo_init(struct aic_sdmc_host *host, u32 *thd) {
  if (*thd == 0) {
    u32 depth = 0;

    depth = sdmc_readl(host, SDMC_FIFOCFG);
    depth = ((depth & RX_WMARK_MASK) >> RX_WMARK_SHIFT) + 1;
    *thd = MSIZE(0x2) | RX_WMARK(depth / 2 - 1) | TX_WMARK(depth / 2);
  }
  sdmc_writel(host, SDMC_FIFOCFG, *thd);
  sdmc_writel(host, SDMC_CTC,
              (512 << SDMC_CTC_CARDTHR_SHIFT) | SDMC_CTC_CARDRDTHR_EN);
}

void hal_sdmc_soft_reset(struct aic_sdmc_host *host) {
  u32 temp = 0;

  temp = sdmc_readl(host, SDMC_INTEN);
  sdmc_writel(host, SDMC_INTEN, 0);

  sdmc_writel(host, SDMC_IDMAINTEN, 0);

  if (hal_sdmc_reset(host, SDMC_HCTRL1_RESET_ALL)) {
    pr_err("Failed to reset!\n");
    return;
  }

  sdmc_writel(host, SDMC_INTEN, temp);

  hal_sdmc_set_cmd(host,
                   SDMC_CMD_PRV_DAT_WAIT | SDMC_CMD_UPD_CLK | SDMC_CMD_START);

  if (hal_sdmc_wait_cmd_started(host)) {
    pr_err("Failed to wait cmd started!\n");
    return;
  }

  temp = sdmc_readl(host, SDMC_OINTST);
  sdmc_writel(host, SDMC_OINTST, temp);
}

void hal_sdmc_init(struct aic_sdmc_host *host) {
  sdmc_writel(host, SDMC_OINTST, 0xFFFFFFFF);
  sdmc_writel(host, SDMC_INTEN, 0);

  sdmc_writel(host, SDMC_TTMC, 0xFFFFFFFF);

  sdmc_writel(host, SDMC_IDMAINTEN, 0);
  sdmc_writel(host, SDMC_PBUSCFG, 1);

#ifdef CONFIG_AIC_SDMC_IRQ_MODE
  sdmc_writel(host, SDMC_HCTRL1,
              sdmc_readl(host, SDMC_HCTRL1) | SDMC_HCTRL1_INT_EN);
  sdmc_writel(host, SDMC_INTEN, SDMC_INT_DAT_DONE);
  host->complete = aicos_sem_create(0);
#endif
}

