static int g_slotno[AIC_SDIO_NSLOTS];

/****************************************************************************
 * Private Functions
 ****************************************************************************/

__attribute__((weak)) bool board_aic_sdcard_detect(int slotno) {

#ifdef CONFIG_AIC_CARD_DETECT_BY_GPIO
  static bool det_init = false;
  if (slotno == 1) {
    unsigned int value;
    int pin;

    pin = hal_gpio_name2pin(CONFIG_AIC_SDMC1_HOTPLUG_PIN);
    if (pin < 0) {
      mcerr("ERROR: invalid SDMC1 hotplug pin: %s\n",
            CONFIG_AIC_SDMC1_HOTPLUG_PIN);
      return false;
    }
    if (!det_init) {
      mcinfo("INFO: det_init: %s\n", CONFIG_AIC_SDMC1_HOTPLUG_PIN);
      hal_gpio_set_func(GPIO_GROUP(pin), GPIO_GROUP_PIN(pin), PIN_FUNC_GPIO);
      hal_gpio_direction_input(GPIO_GROUP(pin), GPIO_GROUP_PIN(pin));

      /* CD# is pulled high on the board and is low when a card is inserted. */
      hal_gpio_set_bias_pull(GPIO_GROUP(pin), GPIO_GROUP_PIN(pin), PIN_PULL_UP);

      det_init = true;
    }
    if (hal_gpio_get_value(GPIO_GROUP(pin), GPIO_GROUP_PIN(pin), &value) < 0) {
      return false;
    }

    return value == 0;
  }
  /*
   * Override this weak symbol if a different slot uses a board-specific
   * card-detect GPIO.
   */
#endif
  UNUSED(slotno);
  return true;
}

static int aic_mmcsd_mount(int slotno, bool is_mount) {
  if (slotno != 1) {
    mcerr("ERROR: Invalid slot number: %d\n", slotno);
    return -EINVAL;
  }

  if (is_mount) {
    int ret = mount(D12X_SDHC_AUTOMOUNT_BLKDEV, CONFIG_AUTO_MOUNT_PATH,
                    CONFIG_AUTO_MOUNT_FSTYPE, MS_NOSUID | MS_SYNCHRONOUS, NULL);
    if (ret >= 0) {
      mcinfo("micro_sd %d: mount success: %d\n", __LINE__, ret);
    } else {
      mcinfo("micro_sd %d: mount failed: %d\n", __LINE__, ret);
    }
    return ret;
  } else {
    int ret = umount2(CONFIG_AUTO_MOUNT_PATH, MNT_DETACH);
    if (ret == 0) {
      mcinfo("micro_sd %d: unmount success\n", __LINE__);
    } else {
      mcinfo("micro_sd %d: unmount failed: %d\n", __LINE__, ret);
    }
    return ret;
  }
}

static void aic_sdcard_hotplug_worker(void *arg) {
  int slotno = *(int *)arg;
  bool present = board_aic_sdcard_detect(slotno);

  /* Require several identical samples before changing media state. */
  if (present != g_detected[slotno]) {
    g_detected[slotno] = present;
    g_detect_count[slotno] = 1;
  } else if (g_detect_count[slotno] < AIC_SDIO_HOTPLUG_STABLE_SAMPLES) {
    g_detect_count[slotno]++;
  }

  if (g_detect_count[slotno] >= AIC_SDIO_HOTPLUG_STABLE_SAMPLES &&
      present != g_inserted[slotno]) {
    if (g_sdio[slotno] == NULL || !g_mmc_bound[slotno]) {
      mcerr("ERROR: SDMC%d media change before MMC/SD binding\n", slotno);
    } else if (present) {
      int ret;

      /* mmcsd_slotinitialize() is one-time setup. Insertion is reported
       * through the media-change callback registered by that function.
       */
      sdio_mediachange(g_sdio[slotno], true);
      ret = aic_mmcsd_mount(slotno, true);
      g_mounted[slotno] = ret == OK;
      mcinfo("SD card inserted, detect raw=0 present=1\n");
      g_inserted[slotno] = true;
    } else {
      if (g_mounted[slotno]) {
        aic_mmcsd_mount(slotno, false);
        g_mounted[slotno] = false;
      }

      sdio_mediachange(g_sdio[slotno], false);
      mcinfo("SD card removed, detect raw=1 present=0\n");
      g_inserted[slotno] = false;
    }

    g_detect_count[slotno] = 0;
  }

  work_queue(LPWORK, &g_hotplug_work[slotno], aic_sdcard_hotplug_worker,
             &g_slotno[slotno], MSEC2TICK(AIC_SDIO_HOTPLUG_POLL_MS));
}

