  g_inserted[slotno] = false;
  g_detected[slotno] = present;
  g_detect_count[slotno] = 0;

  mcinfo("INFO: slotno=%d, detect present=%d, media=0 (probe deferred)\n",
         slotno, present ? 1 : 0);

  /* Keep the media state empty until mmcsd_slotinitialize() registers its
   * callback.  The first stable insertion sample will start probing.
   */
  sdio_mediachange(g_sdio[slotno], false);

  ret = mmcsd_slotinitialize(slotno, g_sdio[slotno]);
  if (ret != OK) {
    mcerr("ERROR: mmcsd_slotinitialize(%d) failed: %d\n", slotno, ret);
    return ret;
  }

  g_mmc_bound[slotno] = true;
  work_queue(LPWORK, &g_hotplug_work[slotno], aic_sdcard_hotplug_worker,
             &g_slotno[slotno], MSEC2TICK(AIC_SDIO_HOTPLUG_POLL_MS));
  return OK;
