    61	    int pin;
    62	
    63	    pin = hal_gpio_name2pin(CONFIG_AIC_SDMC1_HOTPLUG_PIN);
    64	    if (pin < 0) {
    65	      mcerr("ERROR: invalid SDMC1 hotplug pin: %s\n",
    66	            CONFIG_AIC_SDMC1_HOTPLUG_PIN);
    67	      return false;
    68	    }
    69	    if (!det_init) {
    70	      mcinfo("INFO: det_init: %s\n", CONFIG_AIC_SDMC1_HOTPLUG_PIN);
    71	      hal_gpio_set_func(GPIO_GROUP(pin), GPIO_GROUP_PIN(pin), PIN_FUNC_GPIO);
    72	      hal_gpio_direction_input(GPIO_GROUP(pin), GPIO_GROUP_PIN(pin));
    73	
    74	      /* CD# is pulled high on the board and is low when a card is inserted. */
    75	      hal_gpio_set_bias_pull(GPIO_GROUP(pin), GPIO_GROUP_PIN(pin), PIN_PULL_UP);
    76	
