   448	static uint32_t aic_sdio_get_best_div(uint32_t sclk, uint32_t target_freq) {
   449	  AIC_SDIO_LOG_ARGS("sclk=%" PRIu32 " target_freq=%" PRIu32, sclk, target_freq);
   450	  uint32_t down;
   451	  uint32_t up;
   452	  uint32_t f_down;
   453	  uint32_t f_up;
   454	
   455	  down = sclk / target_freq;
   456	  up = DIV_ROUND_UP(sclk, target_freq);
   457	
   458	  f_down = down == 0 ? sclk : sclk / down;
   459	  f_up = up == 0 ? sclk : sclk / up;
   460	
   461	  if ((f_down - target_freq) < (target_freq - f_up)) {
   462	    return down;
   463	  }
   464	
   465	  return up;
   466	}
