   714	static int aic_sdio_wait_cmd(struct aic_sdio_priv_s *priv, uint32_t *mask) {
   715	  AIC_SDIO_LOG_ARGS("priv=%p mask=%p", priv, mask);
   716	  clock_t start = clock_systime_ticks();
   717	  clock_t timeout = MSEC2TICK(AIC_SDIO_CMD_TIMEOUT_MS);
   718	
   719	  for (;;) {
   720	    uint32_t stat = hal_sdmc_int_stat(&priv->host);
   721	
   722	    if ((stat & SDMC_INT_FROM_SDIO) != 0) {
   723	      hal_sdmc_int_clr(&priv->host, SDMC_INT_FROM_SDIO);
   724	      aic_sdio_dispatch_function_irq(priv);
   725	      stat &= ~SDMC_INT_FROM_SDIO;
   726	    }
   727	
   728	    if (stat &
   729	        (SDMC_INT_RTO | SDMC_INT_RESP_ERR | SDMC_INT_RCRC | SDMC_INT_HLE)) {
   730	      *mask = stat;
   731	      return -EIO;
   732	    }
   733	
   734	    if (stat & SDMC_INT_CMD_DONE) {
   735	      *mask = stat;
   736	      return OK;
   737	    }
   738	
   739	    /* Some controllers may not raise CMD_DONE for data commands, but
   740	     * RXDR/TXDR/DAT_DONE indicates command/data path has progressed.
   741	     */
   742	
   743	    if (priv->cmd_has_data &&
   744	        (stat & (SDMC_INT_RXDR | SDMC_INT_TXDR | SDMC_INT_DAT_DONE)) != 0) {
   745	      *mask = stat;
   746	      return OK;
   747	    }
   748	
   749	    if ((clock_systime_ticks() - start) > timeout) {
   750	      *mask = stat;
   751	      return -ETIMEDOUT;
   752	    }
   753	
   754	    if (!priv->pdata->is_sdio) {
   755	      /* Do not starve application threads while waiting for a card response. */
   756	      nxsig_usleep(1000);
   757	    }
   758	  }
   759	}
   760	
   761	static int aic_sdio_wait_data(struct aic_sdio_priv_s *priv,
   762	                              sdio_eventset_t *event) {
   763	  AIC_SDIO_LOG_ARGS("priv=%p event=%p", priv, event);
   764	  clock_t start = clock_systime_ticks();
   765	  clock_t timeout =
   766	      MSEC2TICK(priv->wait_timeout_ms == 0 ? aic_sdio_data_timeout(priv)
   767	                                           : priv->wait_timeout_ms);
   768	
   769	  for (;;) {
   770	    uint32_t stat = hal_sdmc_int_stat(&priv->host);
   771	    size_t old_remaining = priv->remaining_words;
   772	
   773	    if ((stat & SDMC_INT_FROM_SDIO) != 0) {
   774	      hal_sdmc_int_clr(&priv->host, SDMC_INT_FROM_SDIO);
   775	      aic_sdio_dispatch_function_irq(priv);
   776	      stat &= ~SDMC_INT_FROM_SDIO;
   777	    }
   778	
   779	    if ((stat & SDMC_DATA_TOUT) != 0) {
   780	      AIC_SDIO_LOG_ARGS("data timeout stat=0x%08" PRIx32 " rem_words=%zu", stat,
   781	                        priv->remaining_words);
   782	      *event = SDIOWAIT_TIMEOUT;
   783	      return -ETIMEDOUT;
   784	    }
   785	
   786	    if ((stat & SDMC_DATA_ERR) != 0) {
   787	      AIC_SDIO_LOG_ARGS("data error stat=0x%08" PRIx32 " rem_words=%zu", stat,
   788	                        priv->remaining_words);
   789	      *event = SDIOWAIT_ERROR;
   790	      return -EIO;
   791	    }
   792	
   793	    if (priv->remaining_words > 0) {
   794	      if (!priv->write_xfr && (stat & (SDMC_INT_RXDR | SDMC_INT_DAT_DONE))) {
   795	        priv->remaining_words = hal_sdmc_data_rx(
   796	            &priv->host, (u32 *)priv->buffer, priv->remaining_words);
   797	      } else if (priv->write_xfr && (stat & SDMC_INT_TXDR)) {
   798	        priv->remaining_words = hal_sdmc_data_tx(
   799	            &priv->host, (u32 *)priv->buffer, priv->remaining_words);
   800	      }
   801	
   802	      priv->buffer +=
   803	          (old_remaining - priv->remaining_words) * sizeof(uint32_t);
   804	    }
   805	
   806	    if (stat & SDMC_INT_DAT_DONE) {
   807	      *event = SDIOWAIT_TRANSFERDONE;
   808	      return OK;
   809	    }
   810	
   811	    if ((clock_systime_ticks() - start) > timeout) {
   812	      *event = SDIOWAIT_TIMEOUT;
   813	      return -ETIMEDOUT;
   814	    }
   815	
   816	    if (!priv->pdata->is_sdio) {
   817	      /* A missing or unstable card must not turn this wait into a busy loop. */
   818	      nxsig_usleep(1000);
   819	    }
   820	  }
   821	}
