   823	static int aic_sdio_prepare_transfer(struct aic_sdio_priv_s *priv,
   824	                                     uint8_t *buffer, size_t nbytes,
   825	                                     bool write) {
   826	  AIC_SDIO_LOG_ARGS("priv=%p buffer=%p nbytes=%zu write=%d", priv, buffer,
   827	                    nbytes, write ? 1 : 0);
   828	  if ((nbytes == 0) || ((nbytes & 3) != 0)) {
   829	    return -EINVAL;
   830	  }
   831	
   832	  if (priv->blocklen == 0) {
   833	    priv->blocklen = 512;
   834	  }
   835	
   836	  if (priv->nblocks == 0) {
   837	    priv->nblocks = 1;
   838	  }
   839	
   840	  hal_sdmc_set_blk(&priv->host, priv->blocklen, priv->nblocks);
   841	  if (hal_sdmc_reset(&priv->host, SDMC_HCTRL1_FIFO_RESET) != 0) {
   842	    mcerr("ERROR: SDMC%d FIFO reset failed\n", priv->pdata->id);
   843	    return -EIO;
   844	  }
   845	  priv->buffer = buffer;
   846	  priv->remaining_words = nbytes / sizeof(uint32_t);
   847	  priv->write_xfr = write;
   848	  priv->data_active = true;
   849	  return OK;
   850	}
