   863	  mcerr("ERROR: SDMC%d transfer recovery, intstat=0x%08" PRIx32 "\n",
   864	        priv->pdata->id, stat);
   865	  hal_sdmc_int_clr(&priv->host, AIC_SDIO_HOST_INT_MASK);
   866	  aic_sdio_finish_transfer(priv);
