  1081	static int aic_sdio_sendcmd(struct sdio_dev_s *dev, uint32_t cmd,
  1082	                            uint32_t arg) {
  1083	  AIC_SDIO_LOG_ARGS(" START dev=%p cmd=%s(0x%08" PRIx32 ") arg=0x%08" PRIx32,
  1084	                    dev, get_cmd_name(cmd), cmd, arg);
  1085	  struct aic_sdio_priv_s *priv = aic_priv(dev);
  1086	  clock_t start;
  1087	
  1088	  if (aic_sdio_hwinit(priv) < 0) {
  1089	    priv->cmd_ret = -ENODEV;
  1090	    return -ENODEV;
  1091	  }
  1092	
  1093	  if (((cmd & MMCSD_CMDIDX_MASK) >> MMCSD_CMDIDX_SHIFT) != MMCSD_CMDIDX12) {
  1094	    start = clock_systime_ticks();
  1095	    while (hal_sdmc_is_busy(&priv->host) != 0) {
  1096	      if ((clock_systime_ticks() - start) >
  1097	          MSEC2TICK(AIC_SDIO_BUSY_TIMEOUT_MS)) {
  1098	        priv->cmd_ret = -EBUSY;
  1099	        priv->cmd_stat = hal_sdmc_int_stat(&priv->host);
  1100	        aic_sdio_recover(priv);
  1101	        return -EBUSY;
  1102	      }
  1103	
  1104	      if (!priv->pdata->is_sdio) {
  1105	        nxsig_usleep(1000);
  1106	      }
  1107	    }
  1108	  }
  1109	
  1110	  hal_sdmc_int_clr(&priv->host, AIC_SDIO_HOST_INT_MASK);
  1111	  priv->cmd_ret = -EINPROGRESS;
  1112	  priv->cmd_stat = 0;
  1113	  priv->cmd_has_data = ((cmd & MMCSD_DATAXFR_MASK) != MMCSD_NODATAXFR);
  1114	  hal_sdmc_set_arg(&priv->host, arg);
  1115	  hal_sdmc_set_cmd(&priv->host, aic_sdio_build_cmdflags(cmd));
  1116	  AIC_SDIO_LOG_ARGS(" END dev=%p cmd=%s arg=0x%08" PRIx32, dev,
  1117	                    get_cmd_name(cmd), arg);
  1118	  return OK;
  1119	}
