  1156	static int aic_sdio_waitresponse(struct sdio_dev_s *dev, uint32_t cmd) {
  1157	  AIC_SDIO_LOG_ARGS("dev=%p cmd=%s", dev, get_cmd_name(cmd));
  1158	  struct aic_sdio_priv_s *priv = aic_priv(dev);
  1159	  uint32_t mask = 0;
  1160	  uint32_t clear = 0;
  1161	  int ret;
  1162	
  1163	  ret = aic_sdio_wait_cmd(priv, &mask);
  1164	  priv->cmd_ret = ret;
  1165	  priv->cmd_stat = mask;
  1166	  clear = mask & (SDMC_INT_CMD_DONE | SDMC_INT_RTO | SDMC_INT_RESP_ERR |
  1167	                  SDMC_INT_RCRC | SDMC_INT_HLE);
  1168	  if (clear != 0) {
  1169	    hal_sdmc_int_clr(&priv->host, clear);
  1170	  }
