    89	    mcerr("ERROR: Invalid slot number: %d\n", slotno);
    90	    return;
    91	  }
    92	
    93	  if (is_mount) {
    94	    int ret = mount(D12X_SDHC_AUTOMOUNT_BLKDEV, CONFIG_AUTO_MOUNT_PATH,
    95	                    CONFIG_AUTO_MOUNT_FSTYPE, MS_NOSUID | MS_SYNCHRONOUS, NULL);
