   111	static void aic_sdcard_hotplug_worker(void *arg) {
   112	  int slotno = *(int *)arg;
   113	  bool present = false;
   114	  present = board_aic_sdcard_detect(slotno);
   115	  if (present != g_inserted[slotno]) {
   116	    if (present) {
   117	      sdio_mediachange(g_sdio[slotno], present);
   118	      int minor = slotno; // Assuming minor number is same as slot number
   119	      int ret = mmcsd_slotinitialize(minor, g_sdio[slotno]);
   120	      if (ret == OK) {
   121	        aic_mmcsd_mount(slotno, true);
   122	      }
   123	      mcinfo("SD card %s\n", present ? "inserted" : "removed");
   124	      g_inserted[slotno] = present;
   125	    } else {
   126	      aic_mmcsd_mount(slotno, false);
   127	      sdio_mediachange(g_sdio[slotno], present);
   128	      mcinfo("SD card %s\n", present ? "inserted" : "removed");
   129	      g_inserted[slotno] = present;
   130	    }
   131	  }
   132	
   133	  work_queue(HPWORK, &g_hotplug_work[slotno], aic_sdcard_hotplug_worker,
   134	             &g_slotno[slotno], MSEC2TICK(AIC_SDIO_HOTPLUG_POLL_MS));
   135	}
