   477	static uint32_t aic_sdio_data_timeout(struct aic_sdio_priv_s *priv) {
   478	  AIC_SDIO_LOG_ARGS("priv=%p", priv);
   479	  uint32_t total;
   480	  uint32_t lanes;
   481	  uint32_t timeout;
   482	
   483	  total = priv->blocklen * priv->nblocks;
   484	  lanes = priv->pdata->buswidth == SDMC_CTYPE_8BIT
   485	              ? 8
   486	              : (priv->pdata->buswidth == SDMC_CTYPE_4BIT ? 4 : 1);
   487	  timeout = total * 8;
   488	  timeout /= lanes;
   489	  timeout *= 10;
   490	
   491	  if (priv->clock == 0) {
   492	    return AIC_SDIO_POLL_TIMEOUT_MS;
   493	  }
   494	
   495	  timeout /= MAX(priv->clock / 1000, 1);
   496	  if (priv->ddr_mode) {
   497	    timeout /= 2;
   498	  }
   499	
   500	  return MAX(timeout, 1000u);
   501	}
