   503	static uint32_t aic_sdio_build_cmdflags(uint32_t cmd) {
   504	  AIC_SDIO_LOG_ARGS("cmd=%s", get_cmd_name(cmd));
   505	  uint32_t flags = 0;
   506	  uint32_t cmdidx = (cmd & MMCSD_CMDIDX_MASK) >> MMCSD_CMDIDX_SHIFT;
   507	  uint32_t xfr = cmd & MMCSD_DATAXFR_MASK;
   508	
   509	  if (xfr != MMCSD_NODATAXFR) {
   510	    flags |= SDMC_CMD_DAT_EXP;
   511	    if ((xfr & MMCSD_WRXFR) != 0) {
   512	      flags |= SDMC_CMD_DAT_WR;
   513	    }
   514	  }
   515	
   516	  if ((cmd & MMCSD_RESPONSE_MASK) != MMCSD_NO_RESPONSE) {
   517	    flags |= SDMC_CMD_RESP_EXP;
   518	    if ((cmd & MMCSD_RESPONSE_MASK) == MMCSD_R2_RESPONSE) {
   519	      flags |= SDMC_CMD_RESP_LEN;
   520	    }
   521	  }
   522	
   523	  if (aic_sdio_resp_crc_needed(cmd)) {
   524	    flags |= SDMC_CMD_RESP_CRC;
   525	  }
   526	
   527	  if (cmdidx == MMCSD_CMDIDX0) {
   528	    flags |= SDMC_CMD_INIT;
   529	  }
   530	
   531	  if (cmd & MMCSD_STOPXFR) {
   532	    flags |= SDMC_CMD_STOP;
   533	  } else {
   534	    flags |= SDMC_CMD_PRV_DAT_WAIT;
   535	  }
   536	  AIC_SDIO_LOG_ARGS("flags=0x%08" PRIx32 " cmdidx=0x%08" PRIx32 " \
   537	      cmd_start=0x%08" PRIx32 " use_hold_reg=0x%08" PRIx32,
   538	                    flags, cmdidx, SDMC_CMD_START, SDMC_CMD_USE_HOLD_REG);
   539	  return flags | cmdidx | SDMC_CMD_START | SDMC_CMD_USE_HOLD_REG;
   540	}
