   568	static int aic_sdio_clk_init(struct aic_sdio_priv_s *priv) {
   569	  AIC_SDIO_LOG_ARGS("priv=%p", priv);
   570	  int ret;
   571	
   572	  hal_clk_disable_assertrst(priv->pdata->clk);
   573	  hal_clk_disable(priv->pdata->clk);
   574	  hal_clk_set_freq(priv->pdata->clk, priv->pdata->clk_freq);
   575	  priv->sclk_rate = hal_clk_get_freq(priv->pdata->clk);
   576	  if (priv->pdata->is_sdio) {
   577	    priv->sclk_rate /= 2;
   578	  }
   579	
   580	  mcinfo("Line:%d  sclk_rate=%lu buswidth=%d clk_freq=%lu", __LINE__,
   581	         priv->sclk_rate, priv->pdata->buswidth, priv->pdata->clk_freq);
   582	  ret = hal_clk_enable(priv->pdata->clk);
   583	  if (ret < 0) {
   584	    mcerr("ERROR: SDMC%d clk enable failed\n", priv->pdata->id);
   585	    return ret;
   586	  }
   587	
   588	  ret = hal_clk_enable_deassertrst(priv->pdata->clk);
   589	  if (ret < 0) {
   590	    mcerr("ERROR: SDMC%d reset deassert failed\n", priv->pdata->id);
   591	    return ret;
   592	  }
   593	
   594	  return OK;
   595	}
