   669	static int aic_sdio_hwinit(struct aic_sdio_priv_s *priv) {
   670	  int ret;
   671	
   672	  if (priv->initialized) {
   673	    return OK;
   674	  }
   675	  ret = aic_sdio_clk_init(priv);
   676	  if (ret < 0) {
   677	    return ret;
   678	  }
   679	
   680	  priv->host.base = (volatile void *)priv->pdata->base;
   681	  priv->host.is_sdio = priv->pdata->is_sdio ? 1 : 0;
   682	  priv->host.fifoth_val = MSIZE(2) | RX_WMARK(7) | TX_WMARK(8);
   683	
   684	  ret = hal_sdmc_reset(&priv->host, SDMC_HCTRL1_RESET_ALL);
   685	  if (ret != 0) {
   686	    return -EIO;
   687	  }
   688	
   689	  priv->ddr_mode = priv->pdata->data_rate == SDMC_DDR_MODE;
   690	  priv->blocklen = 512;
   691	  priv->nblocks = 1;
   692	  priv->clock = 0;
   693	  AIC_SDIO_LOG_ARGS("ddr_mode=%d ,", priv->ddr_mode ? 1 : 0);
   694	
   695	  ret = aic_sdio_setup_bus(priv, SDMC_CLOCK_MIN);
   696	  if (ret < 0) {
   697	    return ret;
   698	  }
   699	
   700	  hal_sdmc_init(&priv->host);
   701	  hal_sdmc_fifo_init(&priv->host, &priv->host.fifoth_val);
   702	  hal_sdmc_set_phase(&priv->host, priv->pdata->drv_phase,
   703	                     priv->pdata->smp_phase);
   704	  hal_sdmc_set_ddrmode(&priv->host, priv->ddr_mode ? 1 : 0);
   705	  /* During identification/init sequence the card is in 1-bit mode. */
   706	  hal_sdmc_set_buswidth(&priv->host, SDMC_CTYPE_1BIT);
   707	  hal_sdmc_clk_enable(&priv->host);
   708	
   709	  priv->initialized = true;
   710	  AIC_SDIO_LOG_ARGS("aic_sdio_hwinit END OK");
   711	  return OK;
   712	}
