   949	static void aic_sdio_clock(struct sdio_dev_s *dev, enum sdio_clock_e rate) {
   950	  struct aic_sdio_priv_s *priv = aic_priv(dev);
   951	  mcinfo("Line:%d dev=%p rate=%d sclk_rate=%lu", __LINE__, dev, (int)rate, priv->sclk_rate);
   952	  uint32_t freq;
   953	
   954	  switch (rate) {
   955	  case CLOCK_SDIO_DISABLED:
   956	    hal_sdmc_clk_disable(&priv->host);
   957	    priv->clock = 0;
   958	    return;
   959	
   960	  case CLOCK_IDMODE:
   961	    freq = SDMC_CLOCK_MIN;
   962	    break;
   963	
   964	  case CLOCK_MMC_TRANSFER:
   965	    freq = MIN(priv->sclk_rate, (uint32_t)AIC_SDIO_MMC_FREQ);
   966	    break;
   967	
   968	  case CLOCK_SD_TRANSFER_1BIT:
   969	    freq = MIN(priv->sclk_rate, (uint32_t)AIC_SDIO_SD1_FREQ);
   970	    break;
   971	
   972	  case CLOCK_SD_TRANSFER_4BIT:
   973	  default:
   974	    freq = MIN(priv->sclk_rate, (uint32_t)AIC_SDIO_SD4_FREQ);
   975	    break;
   976	  }
   977	
   978	  if (priv->pdata->is_sdio) {
   979	    freq = MIN(freq, (uint32_t)AIC_SDIO_DEVICE_MAX_FREQ);
   980	  }
   981	
   982	  aic_sdio_setup_bus(priv, freq);
   983	}
