    90	static u32 aic_sdmc_get_timeout(struct aic_sdmc *host, const u32 size)
    91	{
    92	    unsigned int timeout;
    93	
    94	    timeout = size * 8;
    95	    timeout /= (host->buswidth == 0) ? 1 : (host->buswidth == 1) ? 4 : (host->buswidth == 2) ? 8 : 1;
    96	    timeout *= 10;      /* wait 10 times as long */
    97	    timeout /= (host->clock / MSEC_PER_SEC);
    98	    timeout /= host->ddr_mode ? 2 : 1;
    99	    timeout = (timeout < MSEC_PER_SEC) ? MSEC_PER_SEC : timeout;
   100	    return timeout;
   101	}
