   103	static int aic_sdmc_data_transfer(struct aic_sdmc *host,
   104	                                  struct rt_mmcsd_data *data)
   105	{
   106	    int ret = 0;
   107	    u32 mask, size, total;
   108	    rt_tick_t timeout, end, start = rt_tick_get_millisecond();
   109	
   110	    total = data->blksize * data->blks;
   111	    timeout = aic_sdmc_get_timeout(host, total);
   112	
   113	    size = total / 4;
   114	    for (;;) {
   115	        mask = hal_sdmc_int_stat(&host->host);
   116	        if (mask & (SDMC_DATA_ERR | SDMC_DATA_TOUT)) {
   117	            pr_err("Data error! size %d/%d, mode %s-%s, status 0x%x\n",
   118	                   size * 4, total,
   119	                   host->fifo_mode ? "FIFO" : "IDMA",
   120	                   data->flags == DATA_DIR_READ ? "Read" : "Write", mask);
   121	            ret = -EINVAL;
   122	            break;
   123	        }
   124	
   125	        // mmcsd_dbg("%s: mask %#x, size %d, timeout %d\n",
   126	        //           data->flags == DATA_DIR_READ ? "Read" : "Write",
   127	        //           mask, size, timeout);
   128	        if (host->fifo_mode && size) {
   129	            if (data->flags == DATA_DIR_READ &&
   130	                    (mask & (SDMC_INT_RXDR | SDMC_INT_DAT_DONE)))
   131	                size = hal_sdmc_data_rx(&host->host, (u32 *)data->buf, size);
   132	            else if (data->flags == DATA_DIR_WRITE &&
   133	                     (mask & SDMC_INT_TXDR))
   134	                size = hal_sdmc_data_tx(&host->host, (u32 *)data->buf, size);
   135	        }
   136	
   137	        if (mask & SDMC_INT_DAT_DONE) {
   138	            ret = 0;
   139	            break;
   140	        }
   141	
   142	        end = rt_tick_get_millisecond();
   143	        if (end - start > timeout) {
   144	            LOG_W("Data timeout %d - %d > %d! size %d/%d, mode %s-%s, status 0x%x\n",
   145	                    end, start,
   146	                    timeout, size * 4, total,
   147	                    host->fifo_mode ? "FIFO" : "IDMA",
   148	                    data->flags == DATA_DIR_READ ? "Read" : "Write", mask);
   149	            data->err = -RT_ETIMEOUT;
   150	            ret = -RT_ETIMEOUT;
   150	            ret = -RT_ETIMEOUT;
   151	            break;
   152	        }
   153	    }
   154	
   155	    hal_sdmc_int_clr(&host->host, mask);
   156	    return ret;
