   171	static void aic_sdmc_request(struct rt_mmcsd_host *rthost,
   172	                             struct rt_mmcsd_req *req)
   173	{
   174	    struct aic_sdmc *host;
   175	    struct rt_mmcsd_cmd *cmd = req->cmd;
   176	    struct rt_mmcsd_data *data = req->data;
   177	    s32 ret = 0, flags = 0, i;
   178	    u32 retry = SDMC_TIMEOUT;
   179	    u32 mask;
   180	    rt_tick_t timeout = 500;
   181	    rt_tick_t start = rt_tick_get_millisecond();
   182	    struct bounce_buffer bbstate;
   183	    ALLOC_CACHE_ALIGN_BUFFER(struct aic_sdmc_idma_desc, cur_idma,
   184	                             data ? DIV_ROUND_UP(data->blks, 8) : 0);
   185	
   186	    RT_ASSERT(rthost != RT_NULL);
   187	    RT_ASSERT(req != RT_NULL);
   188	
   189	    host = (struct aic_sdmc *)rthost->private_data;
   190	    RT_ASSERT(host != RT_NULL);
   191	
   192	    cmd = req->cmd;
   193	    RT_ASSERT(cmd != RT_NULL);
   194	
   195	    if (cmd->cmd_code != STOP_TRANSMISSION) {
   196	        while (hal_sdmc_is_busy(&host->host)) {
   197	            if (rt_tick_get_millisecond() - start > timeout) {
   198	                pr_warn("Data transfer is busy\n");
   199	                cmd->err = -RT_EBUSY;
   200	                goto out;
   201	            }
   202	        }
   203	    }
   204	
   205	    // pr_debug("cmd_code: %02d, arg: %08x, flags: %08x --> ", cmd->cmd_code, cmd->arg, cmd->flags);
   206	
   207	    hal_sdmc_int_clr(&host->host, SDMC_INT_ALL);
   208	    if (data) {
   209	    #ifdef AIC_SDMC_IRQ_MODE    /* SDIO card always enable AIC_SDMC_IRQ_MODE */
   210	        host->fifo_mode = 0;
   211	    #else
   212	        if ((data->blksize * data->blks) < 512)
   213	            host->fifo_mode = 1;
   214	        else
   215	            host->fifo_mode = 0;
   216	    #endif
   217	
   218	        hal_sdmc_set_blk(&host->host, data->blksize, data->blks);
   219	        hal_sdmc_reset(&host->host, SDMC_HCTRL1_FIFO_RESET);
   220	        if (!host->fifo_mode) {
   221	            ret = hal_sdmc_idma_start(&host->host, data->blksize * data->blks,
   222	                                      data->flags == DATA_DIR_READ,
   223	                                      (u32 *)data->buf, &bbstate);
   224	            if (ret) {
   225	                cmd->err = -RT_ERROR;
   226	                goto out;
   227	            }
   228	
   229	            hal_sdmc_idma_prepare(&host->host, data->blksize, data->blks,
   230	                                  cur_idma, bbstate.bounce_buffer);
   231	        } else {
   232	            if (hal_sdmc_get_idma_status(&host->host))
   233	                hal_sdmc_idma_disable(&host->host);
   234	        }
   235	    }
   236	    if (data)
   237	        mmcsd_dbg("fifo_mode: %d, block: %d x %d\n", host->fifo_mode,
   238	                  data->blksize, data->blks);
   239	    else
   240	        mmcsd_dbg("fifo_mode: %d\n", host->fifo_mode);
   241	
   242	    hal_sdmc_set_arg(&host->host, cmd->arg);
   243	    if (data)
   244	        flags = aic_sdmc_set_transfer_mode(host, data);
   245	
   246	    // if (resp_type(cmd) == RESP_R2) && (cmd->resp_type & MMC_RSP_BUSY))
   247	    //     return -1;
   248	
   249	    if (cmd->cmd_code == GO_IDLE_STATE)
   250	        flags |= SDMC_CMD_INIT;
   251	
   252	    if (cmd->cmd_code == STOP_TRANSMISSION)
   253	        flags |= SDMC_CMD_STOP;
   254	    else
   255	        flags |= SDMC_CMD_PRV_DAT_WAIT;
   256	
   257	    if (resp_type(cmd) != RESP_NONE) {
   258	        flags |= SDMC_CMD_RESP_EXP;
   259	        if (resp_type(cmd) == RESP_R2)
   260	            flags |= SDMC_CMD_RESP_LEN;
   261	    }
   262	
   263	    if (resp_crc_type(cmd))
   264	        flags |= SDMC_CMD_RESP_CRC;
   265	
   266	    flags |= (cmd->cmd_code | SDMC_CMD_START | SDMC_CMD_USE_HOLD_REG);
   267	    hal_sdmc_set_cmd(&host->host, flags);
   268	
   269	    for (i = 0; i < retry; i++) {
   270	        mask = hal_sdmc_int_stat(&host->host);
   271	        if (mask & SDMC_INT_CMD_DONE) {
   272	            if (!data)
   273	                hal_sdmc_int_clr(&host->host, mask);
   274	            break;
   275	        }
   276	    }
   277	    mmcsd_dbg("Flags: 0x%x, mask: 0x%x\n", flags, mask);
   278	
   279	    if (i == retry) {
   280	        LOG_W("CMD%d done timeout.\n", cmd->cmd_code);
   281	        cmd->err = -RT_ETIMEOUT;
   282	        goto out;
   283	    }
   284	
   285	    if (mask & SDMC_INT_RTO) {
   286	        pr_debug("CMD%d Response Timeout.\n", cmd->cmd_code);
   287	        cmd->err = -RT_ETIMEOUT;
   288	        goto out;
   289	    } else if (mask & SDMC_INT_RESP_ERR) {
   290	        pr_err("CMD%d Response Error.\n", cmd->cmd_code);
   291	        cmd->err = -RT_EIO;
   292	        goto out;
   293	    } else if (resp_crc_type(cmd) && (mask & SDMC_INT_RCRC)) {
   294	        pr_err("CMD%d Response CRC Error.\n", cmd->cmd_code);
   295	        cmd->err = -RT_EINVAL;
   296	        goto out;
   297	    }
   298	
   299	    if (resp_type(cmd) != RESP_NONE)
   300	        hal_sdmc_get_rsp(&host->host, (u32 *)cmd->resp, resp_type(cmd) == RESP_R2);
   301	
   302	    if (data) {
   303	#ifndef AIC_SDMC_IRQ_MODE
   304	        aic_sdmc_data_transfer(host, data);
   305	        if (!(host->fifo_mode))
   306	            hal_sdmc_idma_stop(&host->host, &bbstate,
   307	                               data->flags == DATA_DIR_READ);
   308	#else
   309	        hal_sdmc_idma_stop(&host->host, &bbstate,data->flags == DATA_DIR_READ);
   310	#endif
   311	    }
   312	
   313	out:
   314	    mmcsd_req_complete(rthost);
   315	}
