   317	static u32 aic_sdmc_get_best_div(u32 sclk, u32 target_freq)
   318	{
   319	    u32 down, up, f_down, f_up;
   320	
   321	    down = sclk / target_freq;
   322	    up = DIV_ROUND_UP(sclk, target_freq);
   323	
   324	    f_down = down == 0 ? sclk : sclk / down;
   325	    f_up = up == 0 ? sclk : sclk / up;
   326	
   327	    /* Select the closest div parameter */
   328	    if ((f_down - target_freq) < (target_freq - f_up))
   329	        return down;
   330	    return up;
   331	}
