   333	static int aic_sdmc_setup_bus(struct aic_sdmc *host, u32 freq)
   334	{
   335	    u32 mux, div, sclk = host->sclk_rate;
   336	
   337	    if ((freq == host->clock && host->ddr_mode == 0) || (freq == 0))
   338	        return 0;
   339	
   340	    if (sclk == freq) {
   341	        /* bypass mode */
   342	        mux = 1;
   343	        div = 0;
   344	    } else {
   345	        div = aic_sdmc_get_best_div(sclk, freq);
   346	
   347	        if (div <= 4) {
   348	            mux = DIV_ROUND_UP(div, 2);
   349	        } else {
   350	            if (div % 8)
   350	            if (div % 8)
   351	                mux = 2;
   352	            else
   353	                mux = 4;
   354	        }
   355	        div /= mux * 2;
   356	        if (div > SDMC_CLKCTRL_DIV_MAX)
   357	            div = SDMC_CLKCTRL_DIV_MAX;
   358	    }
   359	
   360	    if (host->ddr_mode) {
   361	        //ddr mode div must set 0
   362	        div = 0;
   363	        mux = aic_sdmc_get_best_div(sclk * 2, freq);
   364	    }
   365	
   366	    aic_sdmc_set_ext_clk_mux(&host->host, mux);
   367	    LOG_I("SDMC%d, sclk %d KHz, clk expt %d KHz(act %d KHz), div %d-%d\n",
   368	            host->index, sclk / 1000, freq / 1000,
   369	            div ? sclk / mux / div / 2 / 1000 : sclk / mux / 1000,
   370	            mux, div * 2);
   371	
   372	    hal_sdmc_set_div(&host->host, div);
   373	    hal_sdmc_set_cmd(&host->host,
   374	                    SDMC_CMD_PRV_DAT_WAIT | SDMC_CMD_UPD_CLK | SDMC_CMD_START);
   375	
   376	    if (hal_sdmc_wait_cmd_started(&host->host))
   377	        return -RT_ETIMEOUT;
   378	
   379	    hal_sdmc_clk_enable(&host->host);
   380	    hal_sdmc_set_cmd(&host->host,
   381	                    SDMC_CMD_PRV_DAT_WAIT | SDMC_CMD_UPD_CLK | SDMC_CMD_START);
   382	
   383	    if (hal_sdmc_wait_cmd_started(&host->host))
   384	        return -RT_ETIMEOUT;
   385	
   386	    host->clock = freq;
   387	    return 0;
   388	}
