static int aic_sdio_waitresponse(struct sdio_dev_s *dev, uint32_t cmd) {
  AIC_SDIO_LOG_ARGS("dev=%p cmd=%s", dev, get_cmd_name(cmd));
  struct aic_sdio_priv_s *priv = aic_priv(dev);
