  uint32_t clear = 0;
  int ret;

  ret = aic_sdio_wait_cmd(priv, &mask);
  priv->cmd_ret = ret;
  priv->cmd_stat = mask;
  clear = mask & (SDMC_INT_CMD_DONE | SDMC_INT_RTO | SDMC_INT_RESP_ERR |
                  SDMC_INT_RCRC | SDMC_INT_HLE);
  if (clear != 0) {
    hal_sdmc_int_clr(&priv->host, clear);
