   597	static int aic_sdio_setup_bus(struct aic_sdio_priv_s *priv, uint32_t freq) {
   598	  mcinfo("priv=%p freq=%d", priv, freq);
   599	  uint32_t mux;
   600	  uint32_t div;
   601	  uint32_t actual;
   602	
   603	  if (freq == 0) {
   604	    return OK;
   605	  }
   606	
   607	  if ((freq == priv->clock) && !priv->ddr_mode) {
   608	    return OK;
   609	  }
   610	
   611	  if (priv->sclk_rate == freq) {
   612	    mux = 1;
   613	    div = 0;
   614	  } else {
   615	    div = aic_sdio_get_best_div(priv->sclk_rate, freq);
   616	    if (div <= 4) {
   617	      mux = DIV_ROUND_UP(div, 2);
   618	    } else {
   619	      mux = (div % 8) ? 2 : 4;
   620	    }
   621	
   622	    div /= mux * 2;
   623	    if (div > SDMC_CLKCTRL_DIV_MAX) {
   624	      div = SDMC_CLKCTRL_DIV_MAX;
   625	    }
   626	  }
   627	
   628	  if (priv->ddr_mode) {
   629	    div = 0;
   630	    mux = aic_sdio_get_best_div(priv->sclk_rate * 2, freq);
   631	  }
   632	
   633	  actual = div ? priv->sclk_rate / mux / div / 2 : priv->sclk_rate / mux;
   634	  mcinfo(" SDMC%d, sclk %u KHz, clk expt %u KHz(act %u KHz), div %u-%u\n",
   635	         priv->pdata->id, priv->sclk_rate / 1000, freq / 1000, actual / 1000,
   636	         mux, div * 2);
   637	
   638	  aic_sdmc_set_ext_clk_mux(&priv->host, mux);
   639	  hal_sdmc_set_div(&priv->host, div);
   640	  hal_sdmc_set_cmd(&priv->host,
   641	                   SDMC_CMD_PRV_DAT_WAIT | SDMC_CMD_UPD_CLK | SDMC_CMD_START);
   642	  if (hal_sdmc_wait_cmd_started(&priv->host) != 0) {
   643	    return -ETIMEDOUT;
   644	  }
   645	
   646	  hal_sdmc_clk_enable(&priv->host);
   647	  hal_sdmc_set_cmd(&priv->host,
   648	                   SDMC_CMD_PRV_DAT_WAIT | SDMC_CMD_UPD_CLK | SDMC_CMD_START);
   649	  if (hal_sdmc_wait_cmd_started(&priv->host) != 0) {
   650	    return -ETIMEDOUT;
   651	  }
   652	
   653	  /* ID mode is sensitive to sampling edge on some boards/cards.
   654	   * Use a conservative sampling phase at very low clock and restore
   655	   * board-configured phases for transfer clocks.
   656	   */
   657	
   658	  if (freq <= SDMC_CLOCK_MIN) {
   659	    hal_sdmc_set_phase(&priv->host, priv->pdata->drv_phase, 1);
   660	  } else {
   661	    hal_sdmc_set_phase(&priv->host, priv->pdata->drv_phase,
   662	                       priv->pdata->smp_phase);
   663	  }
   664	
   665	  priv->clock = freq;
   666	  return OK;
   667	}
